import { loadEnv, botToken, DISCORD_API, AVA_CHANNELS, watchChannels } from './src/config.mjs';
import { authHeaders } from './src/discordApi.mjs';

const msgId = '1533250855288049714';
const content = 'Working on it babe <3';
const env = await loadEnv();
const headers = authHeaders(botToken(env));
const channels = [...new Set([
  ...Object.values(AVA_CHANNELS).filter((v) => /^\d{10,}$/.test(String(v))),
  ...watchChannels(env),
])];

let found = null;
for (const ch of channels) {
  const res = await fetch(DISCORD_API + '/channels/' + ch + '/messages/' + msgId, { headers });
  if (res.ok) {
    const m = await res.json();
    found = { channelId: ch, message: m };
    break;
  }
  if (res.status !== 404) {
    const t = await res.text();
    console.error('lookup', ch, res.status, t.slice(0, 120));
  }
}
if (!found) {
  console.error('message not found in known channels');
  process.exit(1);
}
console.log('found in', found.channelId, 'author', found.message.author?.username, 'content', String(found.message.content||'').slice(0,120));
const post = await fetch(DISCORD_API + '/channels/' + found.channelId + '/messages', {
  method: 'POST',
  headers,
  body: JSON.stringify({
    content,
    message_reference: { message_id: msgId },
    allowed_mentions: { parse: [] },
  }),
});
const text = await post.text();
if (!post.ok) {
  console.error('reply failed', post.status, text.slice(0, 300));
  process.exit(1);
}
const out = JSON.parse(text);
console.log('ok', out.id, 'https://discord.com/channels/1516108585740800042/' + found.channelId + '/' + out.id);
"

