New-Item -ItemType Directory -Force -Path $gifs | Out-Null
$maxBytes = 8MB

function Convert-ToDiscordGif([string]$src, [string]$dest, [int]$width = 480, [int]$fps = 10, [double]$maxSec = 8) {
  $ext = [IO.Path]::GetExtension($src).ToLowerInvariant()
  $palette = [IO.Path]::ChangeExtension($dest, '.palette.png')
  if (Test-Path -LiteralPath $dest) { Remove-Item -LiteralPath $dest -Force }
  if (Test-Path -LiteralPath $palette) { Remove-Item -LiteralPath $palette -Force }

  if ($ext -match '\.(png|jpe?g|webp)$') {
    # static → short 2-frame "gif version"
    & $ffmpeg -y -hide_banner -loglevel error -loop 1 -t 1.2 -i $src `
      -vf "scale=${width}:-1:flags=lanczos,fps=2,split[s0][s1];[s0]palettegen=max_colors=128:stats_mode=diff[p];[s1][p]paletteuse=dither=bayer:bayer_scale=5" `
      -gifflags +transdiff $dest
  } elseif ($ext -eq '.gif') {
    & $ffmpeg -y -hide_banner -loglevel error -i $src -t $maxSec `
      -vf "scale=${width}:-1:flags=lanczos,fps=$fps,split[s0][s1];[s0]palettegen=max_colors=128:stats_mode=diff[p];[s1][p]paletteuse=dither=bayer:bayer_scale=5" `
      -gifflags +transdiff $dest
  } else {
    # video
    & $ffmpeg -y -hide_banner -loglevel error -i $src -t $maxSec `
      -vf "scale=${width}:-1:flags=lanczos,fps=$fps,split[s0][s1];[s0]palettegen=max_colors=128:stats_mode=diff[p];[s1][p]paletteuse=dither=bayer:bayer_scale=5" `
      -gifflags +transdiff $dest
  }
  if (Test-Path -LiteralPath $palette) { Remove-Item -LiteralPath $palette -Force -ErrorAction SilentlyContinue }
}

$files = Get-ChildItem -LiteralPath $orig -File | Sort-Object Name
$results = @()
foreach ($f in $files) {
  $id = [IO.Path]::GetFileNameWithoutExtension($f.Name)
  $dest = Join-Path $gifs "$id.gif"
  Write-Host "GIF $id ..."
  $w = 480; $fps = 10; $sec = 8
  Convert-ToDiscordGif $f.FullName $dest $w $fps $sec
  if (-not (Test-Path -LiteralPath $dest)) { Write-Host "  FAIL"; continue }
  $size = (Get-Item -LiteralPath $dest).Length
  # shrink loop if over Discord-safe limit
  while ($size -gt $maxBytes -and ($w -gt 240 -or $fps -gt 6 -or $sec -gt 4)) {
    if ($size -gt $maxBytes -and $w -gt 240) { $w = [math]::Max(240, $w - 80) }
    elseif ($size -gt $maxBytes -and $fps -gt 6) { $fps = [math]::Max(6, $fps - 2) }
    else { $sec = [math]::Max(3, $sec - 1.5) }
    Write-Host "  shrink w=$w fps=$fps sec=$sec (was $([math]::Round($size/1MB,2))MB)"
