  $results += [pscustomobject]@{ id = $id; gif = "$id.gif"; bytes = $size; ok = ($size -le $maxBytes) }
}

$results | ConvertTo-Json | Set-Content 'D:\.1 Work Stations\RootMC\Server Handoffs\Ava Ivy\media\gifs-index.json' -Encoding UTF8
$results | Format-Table -AutoSize
Write-Host "done $($results.Count) gifs"

