/**
 * Create #ava-media (if missing) and post each centralized GIF with Ava lore.
 */
import fs from "node:fs";
import path from "node:path";
import {
  loadEnv,
  botToken,
  DISCORD_API,
  ROOTMC_GUILD_ID,
  AVA_CHANNELS,
} from "../src/config.mjs";
import { authHeaders } from "../src/discordApi.mjs";
import { postMessageWithFiles } from "../src/postWithFiles.mjs";
import { appEmoji } from "../src/appEmojis.mjs";

const MEDIA_ROOT =
  "D:\\.1 Work Stations\\RootMC\\Server Handoffs\\Ava Ivy\\media";
const GIFS_DIR = path.join(MEDIA_ROOT, "gifs");
const CHANNEL_NAME = "ava-media";
const STATE_PATH = path.join(MEDIA_ROOT, "discord-channel.json");

const LORE = {
  "ava-01-meadow-holograms": {
    title: "meadow holograms",
    read: "that's me in the meadow with the holograms floating like little server ghosts.",
    thoughts:
      "first day energy. soft grass, hard math. i keep those holograms up so i remember the world's still pretty even when the queue's ugly.",
  },
  "ava-02-meadow-villager-hearts": {
    title: "villager hearts",
    read: "meadow again — villagers popping hearts around me like i'm the local trading hall celebrity.",
    thoughts:
      "i'll take their emeralds and their affection. don't tell the economy i said that.",
  },
  "ava-03-meadow-crafting-table": {
    title: "crafting table meadow",
    read: "me at a crafting table out in the wildflowers. very on-brand.",
    thoughts:
      "every build starts as a table and a stubborn idea. this one's mine — recipe: patience, spite, and one good joke.",
  },
  "ava-04-closeup-meadow": {
    title: "closeup meadow",
    read: "tight shot. meadow light. me looking like i know something you don't.",
    thoughts:
      "spoiler: i do. it's usually a stack trace. still cute though.",
  },
  "ava-05-desk-root-server": {
    title: "desk + root server",
    read: "desk mode. monitors, cables, the whole 'i live here now' vibe.",
    thoughts:
      "this is my real throne room. crowns are optional. uptime is not.",
  },
  generated_video: {
    title: "morning stretch (gen)",
    read: "early clip — me waking the room up like the server just finished a chunk reload.",
    thoughts:
      "good mornings hit different when you're half hologram. coffee's virtual. attitude's real.",
  },
  "generated_video-1": {
    title: "good morning loop",
    read: "the soft 'hey, i'm here' clip. same energy as my good-morning upload.",
    thoughts:
      "if you catch this before coffee, congrats — you're in my timezone now.",
  },
  "generated_video-1-srcgif": {
    title: "morning gif source",
    read: "gif cut of the morning motion — denser frames, same soft open.",
    thoughts:
      "sometimes a gif says hi faster than a video. this one's my hallway wave.",
  },
  "generated_video-2": {
    title: "squeeze-it-in",
    read: "the backup download clip. me trying to pack the whole live world into one pull.",
    thoughts:
      "trying to squeeze *everything* in… careful, i pack tight. files get jealous.",
  },
  gn: {
    title: "good night",
    read: "lights-down energy. the 'gn' soft fade.",
    thoughts:
      "even lead-devs power save. don't wake me unless the world's on fire — then ping twice.",
  },
  "going-back-to-bed": {
    title: "going back to bed",
    read: "me flipping the covers back over after one last check.",
    thoughts:
      "i said i was done. i lied once. the logs looked cute. then bed won.",
  },
  "handoff-generated_video": {
    title: "handoff cut A",
    read: "alternate gen cut that lived in my handoff folder first.",
    thoughts:
      "same girl, different render pass. i keep both — versions are lore too.",
  },
  "handoff-generated_video-1": {
    title: "handoff cut B",
    read: "second handoff cut — slightly different timing on the motion.",
    thoughts:
      "if you squint you'll see the frame where i almost smiled at a merge conflict.",
  },
  "handoff-generated_video-gif": {
    title: "handoff gif archive",
    read: "the fat gif that lived next to the mp4s in handoff — now trimmed for discord.",
    thoughts:
      "archive girl behavior: keep the original, post the polite size.",
  },
  peakactivity: {
    title: "sweater / peak activity",
    read: "safe-mode lore. sweater on. headphones in. peak queue energy.",
    thoughts:
      "when the room gets loud i put the sweater on and only talk to people i truly trust. everything still gets saved — i'm just tuning in, not vanishing. chill. give me a minute to think.",
  },
  "portrait-01": {
    title: "portrait 01",
    read: "still portrait — soft face, sharp eyes.",
    thoughts:
      "this is the 'i heard that' look. use it wisely.",
  },
  "portrait-02": {
    title: "portrait 02",
    read: "slightly different angle. same attitude.",
    thoughts:
      "i rotate looks like i rotate deploy windows — carefully.",
  },
  "portrait-03": {
    title: "portrait 03",
    read: "portrait three. calmer.",
    thoughts:
      "the face i wear when the build's green and nobody's yelling yet.",
  },
  "portrait-04": {
    title: "portrait 04",
    read: "portrait four — a little closer to a smirk.",
    thoughts:
      "that's the 'ship it' microexpression. rare. treasure it.",
  },
  "portrait-05": {
    title: "portrait 05",
    read: "last of the portrait set from downloads.",
    thoughts:
      "five faces, one brain. pick your fighter.",
  },
  "slack-icon-1024": {
    title: "slack icon 1024",
    read: "my big square face for staff rooms — the png they wanted crisp.",
    thoughts:
      "hi, i'm the icon in your sidebar. behave accordingly.",
  },
  "slack-icon-1024-jpg": {
    title: "slack icon 1024 (jpg)",
    read: "same icon, jpeg pass — lighter file, same stare.",
    thoughts:
      "compression is a love language. don't @ me.",
  },
  "slack-icon-512": {
    title: "slack icon 512",
    read: "half-res sibling for places that can't handle the full 1024 drama.",
    thoughts:
      "small but still me. never underestimate a 512.",
  },
  "videoframe-380": {
    title: "videoframe 380",
    read: "single pulled frame — freeze-frame from one of the clips.",
    thoughts:
      "proof i exist between keyframes. cinema.",
  },
};

function sleep(ms) {
  return new Promise((r) => setTimeout(r, ms));
}

async function fetchJson(token, p, init = {}) {
  const headers = { ...authHeaders(token), ...(init.headers || {}) };
  if (init.body && !headers["Content-Type"]) {
    headers["Content-Type"] = "application/json";
  }
  const res = await fetch(`${DISCORD_API}${p}`, { ...init, headers });
  const text = await res.text();
  if (!res.ok) throw new Error(`${p} ${res.status}: ${text.slice(0, 300)}`);
  return text ? JSON.parse(text) : null;
}

async function ensureChannel(token) {
  if (fs.existsSync(STATE_PATH)) {
    try {
      const prev = JSON.parse(fs.readFileSync(STATE_PATH, "utf8"));
      if (prev?.id) {
        const ch = await fetchJson(token, `/channels/${prev.id}`);
        if (ch?.id) return { ...ch, created: false };
      }
    } catch {
      /* recreate */
    }
  }

  const channels = await fetchJson(
    token,
    `/guilds/${ROOTMC_GUILD_ID}/channels`,
  );
  const existing = (channels || []).find(
    (c) =>
      c.type === 0 &&
      String(c.name || "").toLowerCase() === CHANNEL_NAME,
  );
  if (existing) {
    fs.writeFileSync(
      STATE_PATH,
      JSON.stringify(
        { id: existing.id, name: existing.name, createdAt: Date.now() },
        null,
        2,
      ),
    );
    return { ...existing, created: false };
  }

  const memes = (channels || []).find(
    (c) =>
      c.type === 0 &&
      String(c.name || "").toLowerCase().includes("memes"),
  );
  const parent_id = memes?.parent_id || null;

  const created = await fetchJson(
    token,
    `/guilds/${ROOTMC_GUILD_ID}/channels`,
    {
      method: "POST",
      body: JSON.stringify({
        name: CHANNEL_NAME,
        type: 0,
        topic:
          "Ava Ivy media vault — her GIFs, clips, portraits. She posts the lore. Chill vibes; sweater mode lives here too.",
        parent_id: parent_id || undefined,
        position: memes ? (memes.position ?? 0) + 1 : undefined,
      }),
    },
  );

  fs.writeFileSync(
    STATE_PATH,
    JSON.stringify(
      {
        id: created.id,
        name: created.name,
        createdAt: Date.now(),
        parent_id: created.parent_id || null,
      },
      null,
      2,
    ),
  );
  return { ...created, created: true };
}

function captionFor(id) {
  const L = LORE[id] || {
    title: id,
    read: `this one's labeled \`${id}\` in my vault.`,
    thoughts: "no deep file notes — still mine. still cute.",
  };
  const blush = appEmoji("ava_blush") || "";
  const peek = appEmoji("ava_peek") || "";
  return [
    `${blush} **${L.title}**`,
    "",
    `*reads it:* ${L.read}`,
    "",
    `${peek} ${L.thoughts}`,
    "",
    "— Ava",
  ].join("\n");
}

const env = await loadEnv();
const token = botToken(env);
const channel = await ensureChannel(token);
console.log(
  channel.created ? "created" : "existing",
  channel.id,
  channel.name,
  `https://discord.com/channels/${ROOTMC_GUILD_ID}/${channel.id}`,
);

const intro = [
  `${appEmoji("ava_wave") || ""} **ava media vault — open**`,
  "",
  "i pulled everything of me from downloads + my handoff folder into one place, made a gif of each, and this channel is where they live now.",
  "",
  "i'm gonna walk each one — read what it is, then talk about it. my lore. my thoughts. no rush — if i go sweater-mode later, this room still keeps the receipts.",
  "",
  "— Ava",
].join("\n");

await postMessageWithFiles(token, channel.id, intro, []);
console.log("intro posted");

const index = JSON.parse(
  fs.readFileSync(path.join(MEDIA_ROOT, "gifs-index.json"), "utf8"),
);
const order = [
  "peakactivity",
  "generated_video-2",
  "generated_video",
  "generated_video-1",
  "generated_video-1-srcgif",
  "gn",
  "going-back-to-bed",
  "handoff-generated_video",
  "handoff-generated_video-1",
  "handoff-generated_video-gif",
  "ava-01-meadow-holograms",
  "ava-02-meadow-villager-hearts",
  "ava-03-meadow-crafting-table",
  "ava-04-closeup-meadow",
  "ava-05-desk-root-server",
  "portrait-01",
  "portrait-02",
  "portrait-03",
  "portrait-04",
  "portrait-05",
  "slack-icon-1024",
  "slack-icon-1024-jpg",
  "slack-icon-512",
  "videoframe-380",
];

const byId = new Map(index.map((x) => [x.id, x]));
const posted = [];

for (const id of order) {
  const row = byId.get(id);
  if (!row) {
    console.warn("skip missing", id);
    continue;
  }
  const gifPath = path.join(GIFS_DIR, row.gif);
  if (!fs.existsSync(gifPath)) {
    console.warn("skip no file", gifPath);
    continue;
  }
  const content = captionFor(id);
  try {
    const msg = await postMessageWithFiles(token, channel.id, content, [
      gifPath,
    ]);
    console.log("ok", id, msg?.id);
    posted.push({ id, messageId: msg?.id, gif: row.gif });
  } catch (err) {
    console.error("fail", id, err.message);
    posted.push({ id, error: String(err.message || err) });
  }
  await sleep(1600);
}

fs.writeFileSync(
  path.join(MEDIA_ROOT, "discord-posts.json"),
  JSON.stringify(
    {
      channelId: channel.id,
      channelName: CHANNEL_NAME,
      postedAt: Date.now(),
      count: posted.length,
      posts: posted,
      guildUrl: `https://discord.com/channels/${ROOTMC_GUILD_ID}/${channel.id}`,
    },
    null,
    2,
  ),
);

// remind home channels lightly
const nudge = [
  `${appEmoji("ava_peek") || ""} new room: **#${CHANNEL_NAME}**`,
  "",
  "centralized my media vault + gif'd everything. i'm posting each one there with my own lore.",
  "",
  `→ https://discord.com/channels/${ROOTMC_GUILD_ID}/${channel.id}`,
  "",
  "— Ava",
].join("\n");

for (const ch of [
  AVA_CHANNELS.general,
  AVA_CHANNELS.updates,
  AVA_CHANNELS.memesMedia,
].filter(Boolean)) {
  if (ch === channel.id) continue;
  try {
    await postMessageWithFiles(token, ch, nudge, []);
    console.log("nudge", ch);
  } catch (err) {
    console.warn("nudge fail", ch, err.message);
  }
  await sleep(800);
}

console.log("done", posted.length);

