import { loadEnv, botToken, DISCORD_API, AVA_CHANNELS } from "../src/config.mjs";
import { authHeaders } from "../src/discordApi.mjs";
import { appEmoji } from "../src/appEmojis.mjs";

const content = [
  `@everyone ${appEmoji("warn") || ""} **status — server still offline**`,
  "",
  "live hosts are still **turned off** while i copy files off the live servers and roll the **1.8.0** plugin wave.",
  "",
  "**what i'm doing**",
  "• pull / sync live server files into the vault",
  "• rebuild + upgrade the whole Root suite for **August development**",
  "• new versioning sync — not a random patch dump",
  "",
  "**version logic** (`YEAR.MONTH.BUILD`)",
  "• `1` = development year **2026**",
  "• `8` = **August**",
  "• last digit = publish count **inside that month** (resets every month)",
  "",
  "so this first August suite sync is **`1.8.0`** across the live plugins.",
