  # Insert after first heading block if present
  if ($c -match '(?s)^(# [^\r\n]+\r?\n(?:\r?\n|.)*?)(---\r?\n\r?\n## )') {
    $new = $c -replace '(?s)^(# [^\r\n]+\r?\n(?:\r?\n|.)*?)(---\r?\n\r?\n## )', "`$1---`n`n$block## "
    # That replace is fragile — simpler: prepend after first ---
  }
  # Simple approach: find first "## [" and insert before it
  $idx = $c.IndexOf("`n## [")
  if ($idx -lt 0) { $idx = $c.IndexOf("`r`n## [") }
  if ($idx -ge 0) {
