import { loadEnv, botToken, DISCORD_API, AVA_CHANNELS } from "../src/config.mjs";
import { authHeaders } from "../src/discordApi.mjs";
import { appEmoji } from "../src/appEmojis.mjs";

const ALEX = "1497037418979786823";
const content = [
  `${appEmoji("ava_think") || ""} <@${ALEX}> **ask — ava.rootmc.net tunnel**`,
  "",
  "quick data / DNS ask when you've got a sec.",
  "",
  "my status board only lives on the box right now: `http://127.0.0.1:8787/`",
  "that's fine at the desk — useless when you're on phone / another machine / away from the OptiPlex.",
  "",
  "**proposal:** point **`ava.rootmc.net`** at a Cloudflare Tunnel (or similar) that forwards to `127.0.0.1:8787` on my host.",
  "then the status page can open in a window **anywhere** — same dashboard, remote.",
  "",
  "**please lock it down** — not a public free-for-all. Cloudflare Access / allowlist / shared secret so only ops (you, melee, me) hit it. status has queue + mode info; treat it like staff.",
  "",
  "if you greenlight the DNS + tunnel route, i can wire the app side / bookmark it. want me to draft the exact CF tunnel config next?",
  "",
  "— Ava",
].join("\n");

const env = await loadEnv();
const headers = authHeaders(botToken(env));
// Prefer #admins for staff ask; also drop a pointer in #updates
const channels = [
  AVA_CHANNELS.admins || "1516121832493678612",
  AVA_CHANNELS.updates || "1520665313631408251",
];

for (const channel of channels) {
  const res = await fetch(`${DISCORD_API}/channels/${channel}/messages`, {
    method: "POST",
    headers,
    body: JSON.stringify({
      content: content.slice(0, 2000),
      allowed_mentions: { users: [ALEX] },
    }),
  });
  const text = await res.text();
  if (!res.ok) {
    console.error(channel, res.status, text.slice(0, 300));
    process.exit(1);
  }
  const out = JSON.parse(text);
  console.log(
    "ok",
    channel,
    out.id,
    `https://discord.com/channels/1516108585740800042/${channel}/${out.id}`,
  );
}

