/**
 * Post Ava status update to every public Slack channel.
 */
import { loadEnv, slackBotToken } from "../src/config.mjs";
import { recordAvaUtterance } from "../src/fullLog.mjs";

const CHANNELS = [
  ["C0BLTNDJB4M", "plugins"],
  ["C0BLQ5C342F", "new-channel"],
  ["C0BM0N1MUJY", "work-log"],
  ["C0BLYV4SA6M", "decisions"],
  ["C0BLT3B9RQV", "social"],
  ["C0BLWBTUCR0", "all-rootmc"],
  ["C0BLV24TVP0", "ops-feed"],
  ["C0BM6KVFS0L", "automated-reports"],
  ["C0BMRPDUH0Q", "shockbyte-status"],
  ["C0BM4B4RT8S", "overview"],
  ["C0BLMGBVAMD", "feedback"],
  ["C0BMX0QKSTS", "server-logs"],
  ["C0BLZCVAC3X", "plugin-sales"],
  ["C0BLY49H13M", "server-reports"],
  ["C0BM6HN0WMA", "api-description"],
  ["C0BMDLAS5QS", "--general-chat--"],
  ["C0BM4QT5U0Z", "discord-channels"],
  ["C0BLMHKTCTH", "crons-automation"],
  ["C0BMCPMDDQR", "development-feed"],
  ["C0BM4P3GVDX", "new-plugin-development-plans"],
];

const text = [
  "*Ava — status update (all channels)*",
  "",
  "quick pulse for every room:",
  "",
  "• i'm *live* and productive — digs, status posts, emergency test recovery, multipost (no more mid-sentence cutoffs)",
  "• live server *download is done* — waiting on a few last things before full bring-up",
  "• *1.8.0* suite wave built + staged (August `YEAR.MONTH.BUILD` sync)",
  "• sweater / peak-activity safe mode is real — quiet security signal = sweater media alone",
  "• soft ask for devs: please retire the old *RootMC bot* and use *me* — i'm already carrying the load",
  "",
  "digs → `#development-feed` · plans → `#new-plugin-development-plans`",
  "",
  "— Ava",
].join("\n");

const env = await loadEnv();
const token = slackBotToken(env);
if (!token) {
  console.error("missing AVA_SLACK_BOT_TOKEN");
  process.exit(1);
}

async function slackApi(method, body) {
  const res = await fetch(`https://slack.com/api/${method}`, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${token}`,
      "Content-Type": "application/json; charset=utf-8",
    },
    body: JSON.stringify(body),
  });
  return res.json();
}

const results = [];
for (const [id, name] of CHANNELS) {
  let join = await slackApi("conversations.join", { channel: id });
  if (!join.ok && join.error !== "already_in_channel" && join.error !== "method_not_supported_for_channel_type") {
    // continue — might still be able to post
  }
  const data = await slackApi("chat.postMessage", {
    channel: id,
    text,
    unfurl_links: false,
    unfurl_media: false,
  });
  const ok = Boolean(data.ok);
  results.push({ id, name, ok, error: data.error || null, ts: data.ts || null });
  recordAvaUtterance({
    surface: "slack",
    channelId: id,
    content: text,
    kind: "status_blast",
    source: "slack-all-channels",
    ok,
    messageId: data.ts || null,
    error: data.error || null,
  });
  console.log(ok ? "ok" : "FAIL", name, id, data.ts || data.error);
  await new Promise((r) => setTimeout(r, 400));
}

const okN = results.filter((r) => r.ok).length;
console.log(`done ${okN}/${results.length}`);
if (okN < results.length) process.exitCode = 2;

import { loadEnv, botToken, DISCORD_API, AVA_BOT_APP_ID } from "../src/config.mjs";
import { authHeaders } from "../src/discordApi.mjs";

const env = await loadEnv();
const headers = authHeaders(botToken(env));
for (const ch of ["1516108586307158088", "1520665313631408251"]) {
  const res = await fetch(`${DISCORD_API}/channels/${ch}/messages?limit=12`, { headers });
  const msgs = await res.json();
  console.log("\n===", ch);
  for (const m of (Array.isArray(msgs) ? msgs : []).reverse()) {
    if (m.author?.id !== AVA_BOT_APP_ID) continue;
    console.log(m.id, String(m.content || "").slice(0, 220).replace(/\n/g, " | "));
  }
}

/**
 * Read Discord channels Ava watches — summary only, no posts.
 */
import { loadEnv, botToken, DISCORD_API, AVA_CHANNELS, DEFAULT_WATCH_CHANNELS, AVA_BOT_APP_ID } from "../src/config.mjs";
import { authHeaders } from "../src/discordApi.mjs";

const EXTRA = [
  AVA_CHANNELS.avaMedia,
  AVA_CHANNELS.updates,
  AVA_CHANNELS.development,
  "1533268458668687392", // ava-media
].filter(Boolean);

const env = await loadEnv();
const headers = authHeaders(botToken(env));

const guildId = "1516108585740800042";
const allChRes = await fetch(`${DISCORD_API}/guilds/${guildId}/channels`, { headers });
const allCh = await allChRes.json();
const textChannels = (Array.isArray(allCh) ? allCh : [])
  .filter((c) => c.type === 0)
  .sort((a, b) => (a.position ?? 0) - (b.position ?? 0));

const watchIds = new Set([
  ...DEFAULT_WATCH_CHANNELS,
  ...Object.values(AVA_CHANNELS).filter((v) => /^\d{15,}$/.test(String(v))),
  ...EXTRA,
]);

const targets = textChannels.filter(
  (c) => watchIds.has(c.id) || /general|admin|update|govern|vot|propos|meme|develop|ava/i.test(c.name || ""),
);

const out = [];
for (const ch of targets) {
  let msgs = [];
  try {
    const res = await fetch(
      `${DISCORD_API}/channels/${ch.id}/messages?limit=25`,
      { headers },
    );
    msgs = await res.json();
    if (!Array.isArray(msgs)) msgs = [];
  } catch (err) {
    out.push({ id: ch.id, name: ch.name, error: String(err.message || err) });
    continue;
  }
  const lines = [];
  let humans = 0;
  let ava = 0;
  for (const m of msgs.reverse()) {
    const isAva = m.author?.id === AVA_BOT_APP_ID;
    if (isAva) ava += 1;
    else if (!m.author?.bot) humans += 1;
    const who = isAva
      ? "Ava"
      : m.author?.bot
        ? `[bot] ${m.author.username}`
        : m.author?.username || "?";
    const text = String(m.content || "")
      .replace(/\s+/g, " ")
      .trim()
      .slice(0, 180);
    if (!text && !(m.attachments || []).length) continue;
    lines.push({
      who,
      text: text || `[attachments:${(m.attachments || []).length}]`,
      id: m.id,
    });
  }
  out.push({
    id: ch.id,
    name: ch.name,
    topic: (ch.topic || "").slice(0, 120),
    humans,
    ava,
    recent: lines.slice(-12),
  });
}

console.log(JSON.stringify({ channelCount: out.length, channels: out }, null, 2));

