/**
 * Post governance PROP drafts to Discord #proposals + #voting (Ava bot).
 * Seeds ✅❌➖ on voting message. Does not create D1 legislation rows.
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { postAvaDiscord } from "../src/avaPost.mjs";
import { loadEnv, botToken, AVA_CHANNELS } from "../src/config.mjs";
import { makeFetchJson } from "../src/discordApi.mjs";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const NOTES = path.resolve(
  __dirname,
  "../../../Server Handoffs/Ava Ivy/notes",
);

const PROPS = [
  {
    file: "PROP-root-ava-core.md",
    title: "PROP — Root-Ava-Core plugin (governance)",
    blurb:
      "Authorize design of Paper plugin **Root-Ava-Core** (Ava in-game companion hooks). **No live jar** until Alex greenlights after this vote. Docs filed under Ava Ivy notes.",
  },
  {
    file: "PROP-website-100usd.md",
    title: "PROP — Ava website tools budget (~$100 USD)",
    blurb:
      "One-time **~$100 USD** (not Gold) tools/marketing budget for Ava’s site design. **Do not spend** until this vote passes.",
  },
];

async function seedReactions(fetchJson, channelId, messageId) {
  for (const emoji of ["✅", "❌", "➖"]) {
    try {
      const enc = encodeURIComponent(emoji);
      await fetchJson(
        `/channels/${encodeURIComponent(channelId)}/messages/${encodeURIComponent(messageId)}/reactions/${enc}/@me`,
        { method: "PUT" },
      );
    } catch (err) {
      console.warn("seed", emoji, err.message);
    }
  }
}

async function main() {
  const env = await loadEnv();
  const fetchJson = makeFetchJson(botToken(env));

  for (const p of PROPS) {
    const body = fs.readFileSync(path.join(NOTES, p.file), "utf8");
    const proposalText = [
      `**${p.title}**`,
      "",
      p.blurb,
      "",
      "```",
      body.slice(0, 3500),
      "```",
      "",
      "_Full text also on disk under Server Handoffs/Ava Ivy/notes/_",
    ].join("\n");

    const propMsg = await postAvaDiscord({
      channelId: AVA_CHANNELS.proposals,
      content: proposalText,
      kind: "governance_prop",
      source: "wave-props",
      ackReact: false,
      env,
    });
    console.log("proposals", p.file, propMsg?.id);

    const voteText = [
      `**VOTE (7 days) — ${p.title}**`,
      "",
      p.blurb,
      "",
      "React: ✅ For · ❌ Against · ➖ Abstain",
      "Weighted governance rules apply. Text `for` / `against` / `abstain` also OK.",
    ].join("\n");

    const voteMsg = await postAvaDiscord({
      channelId: AVA_CHANNELS.voting,
      content: voteText,
      kind: "governance_vote_open",
      source: "wave-props",
      ackReact: false,
      env,
    });
    console.log("voting", p.file, voteMsg?.id);
    if (voteMsg?.id) {
      await seedReactions(fetchJson, AVA_CHANNELS.voting, voteMsg.id);
    }
    await new Promise((r) => setTimeout(r, 500));
  }
  console.log("props posted");
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});

