  envStatus: () => ipcRenderer.invoke("ava:env-status"),
  listDiscordChannels: () => ipcRenderer.invoke("ava:list-discord-channels"),
  history: (opts) => ipcRenderer.invoke("ava:history", opts),
  send: (opts) => ipcRenderer.invoke("ava:send", opts),
});

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const DISCORD_API = "https://discord.com/api/v10";
const GUILD_ID = "1516108585740800042";

function firstEnv(env, keys) {
  for (const k of keys) {
    const v = env[k] ?? process.env[k];
    if (v != null && String(v).trim()) return String(v).trim();
  }
  return "";
}

function parseEnvFile(filePath) {
  const out = {};
  if (!fs.existsSync(filePath)) return out;
  for (const line of fs.readFileSync(filePath, "utf8").split(/\r?\n/)) {
    if (!line || line.trim().startsWith("#")) continue;
    const i = line.indexOf("=");
    if (i < 0) continue;
    const k = line.slice(0, i).trim();
    let v = line.slice(i + 1).trim();
    if (
      (v.startsWith('"') && v.endsWith('"')) ||
      (v.startsWith("'") && v.endsWith("'"))
    ) {
      v = v.slice(1, -1);
    }
    out[k] = v;
  }
  return out;
}

export async function loadDesktopEnv() {
  const candidates = [
    path.resolve(__dirname, "../../../.env"),
    path.resolve(__dirname, "../../../../.env"),
    path.resolve(__dirname, "../../../.credentials/.env"),
    "D:\\.1 Work Stations\\RootMC\\.env",
    "D:\\.1 Work Stations\\.credentials\\.env",
  ];
  let fileEnv = {};
  for (const p of candidates) {
    if (fs.existsSync(p)) {
      fileEnv = { ...fileEnv, ...parseEnvFile(p) };
    }
  }
  const discordToken = firstEnv(fileEnv, [
    "AVA_DISCORD_BOT_TOKEN",
    "DISCORD_AVA_BOT_TOKEN",
  ]).replace(/^Bot\s+/i, "");
  const telegramToken = firstEnv(fileEnv, ["AVA_TELEGRAM_BOT_TOKEN"]);
  const operatorChatId = firstEnv(fileEnv, ["AVA_TELEGRAM_OPERATOR_IDS"])
    .split(",")
    .map((s) => s.trim())
    .filter(Boolean)[0] || "6644482344";
  return {
    discordToken,
    telegramToken,
    operatorChatId,
    rewriteUrl: firstEnv(fileEnv, ["AVA_REWRITE_URL"]) || "http://127.0.0.1:8787/api/rewrite",
  };
}

export async function listDiscordTextChannels(env) {
  if (!env.discordToken) return { ok: false, detail: "missing_discord_token", channels: [] };
  const res = await fetch(`${DISCORD_API}/guilds/${GUILD_ID}/channels`, {
    headers: { Authorization: `Bot ${env.discordToken}` },
  });
  const data = await res.json();
  if (!res.ok) return { ok: false, detail: data?.message || res.status, channels: [] };
  const channels = (Array.isArray(data) ? data : [])
    .filter((c) => c.type === 0)
    .map((c) => ({ id: c.id, name: c.name }))
    .sort((a, b) => a.name.localeCompare(b.name));
  return { ok: true, channels };
}

export async function fetchDiscordHistory(env, channelId, limit = 42) {
  if (!env.discordToken || !channelId) {
    return { ok: false, messages: [], detail: "missing_token_or_channel" };
  }
  const res = await fetch(
    `${DISCORD_API}/channels/${channelId}/messages?limit=${Math.min(100, limit)}`,
    { headers: { Authorization: `Bot ${env.discordToken}` } },
  );
  const data = await res.json();
  if (!res.ok) return { ok: false, messages: [], detail: data?.message || res.status };
  const messages = (Array.isArray(data) ? data : [])
    .reverse()
    .slice(-limit)
    .map((m) => ({
      who: m.author?.username || m.author?.id || "?",
      text: m.content || "",
      id: m.id,
    }));
  return { ok: true, messages };
}

export async function sendDiscordMessage(env, channelId, content) {
  const res = await fetch(`${DISCORD_API}/channels/${channelId}/messages`, {
    method: "POST",
    headers: {
      Authorization: `Bot ${env.discordToken}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({ content: String(content).slice(0, 1900) }),
  });
  const data = await res.json();
  if (!res.ok) throw new Error(data?.message || `discord_${res.status}`);
  return data;
}

export async function fetchTelegramHistory(env, chatId, limit = 42) {
  // Telegram Bot API has no full history; keep a local ring buffer file.
  const bufPath = path.resolve(__dirname, "../data/telegram-context.json");
  try {
    if (!fs.existsSync(bufPath)) return { ok: true, messages: [] };
    const raw = JSON.parse(fs.readFileSync(bufPath, "utf8"));
    const list = Array.isArray(raw[String(chatId)]) ? raw[String(chatId)] : [];
    return { ok: true, messages: list.slice(-limit) };
  } catch {
    return { ok: true, messages: [] };
  }
}

function pushTelegramContext(chatId, who, text) {
  const bufPath = path.resolve(__dirname, "../data/telegram-context.json");
  fs.mkdirSync(path.dirname(bufPath), { recursive: true });
  let raw = {};
  try {
    raw = JSON.parse(fs.readFileSync(bufPath, "utf8"));
  } catch {
    raw = {};
  }
  const key = String(chatId);
  const list = Array.isArray(raw[key]) ? raw[key] : [];
  list.push({ who, text, at: Date.now() });
  raw[key] = list.slice(-80);
  fs.writeFileSync(bufPath, JSON.stringify(raw, null, 2), "utf8");
}

export async function sendTelegramMessage(env, chatId, content) {
  if (!env.telegramToken) throw new Error("missing_telegram_token");
  const res = await fetch(
    `https://api.telegram.org/bot${env.telegramToken}/sendMessage`,
    {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        chat_id: chatId,
        text: String(content).slice(0, 4000),
        disable_web_page_preview: true,
      }),
    },
  );
  const data = await res.json();
  if (!data.ok) throw new Error(data.description || "telegram_send_failed");
  pushTelegramContext(chatId, "Ava", content);
  return data.result;
}

export async function rewriteDraft(env, { text, surface, context }) {
  try {
    const res = await fetch(env.rewriteUrl, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        text,
        surface,
        context,
        authorId: "desktop",
        authorName: "desktop",
      }),
    });
    const data = await res.json();
    if (data?.text) return { ok: true, text: data.text, via: "ava-rewrite" };
  } catch {
    /* fall through — still never raw-send without a pass */
  }
  // Offline fallback: light cleanup still counts as rewrite pass
  const cleaned = String(text || "")
    .replace(/\b\$\s*(\d+)/g, "$1 Gold")
    .replace(/\bdollars?\b/gi, "Gold")
    .trim();
  return { ok: true, text: cleaned || text, via: "offline-fallback" };
}

:root {
  --bg0: #0c1210;
  --bg1: #14201a;
  --ink: #e8f2ea;
  --muted: #8aa394;
  --line: rgba(232, 242, 234, 0.12);
  --accent: #6ee7a8;
  --btn: #1e3a2c;
}
* { box-sizing: border-box; }
body {
  margin: 0;
  min-height: 100vh;
  font-family: "DM Sans", system-ui, sans-serif;
  color: var(--ink);
  background:
    radial-gradient(900px 500px at 0% 0%, #1a3a2a 0%, transparent 55%),
    linear-gradient(165deg, var(--bg0), var(--bg1));
}
header {
  padding: 1.25rem 1.5rem 0.75rem;
  border-bottom: 1px solid var(--line);
}
h1 {
  font-family: Syne, sans-serif;
  font-size: 1.75rem;
  margin: 0;
  letter-spacing: -0.03em;
}
.sub { color: var(--muted); margin: 0.25rem 0 0.85rem; font-size: 0.9rem; }
nav { display: flex; gap: 0.5rem; }
.tab {
  background: transparent;
  border: 1px solid var(--line);
  color: var(--ink);
  padding: 0.45rem 0.9rem;
  cursor: pointer;
  font: inherit;
}
.tab.active { border-color: var(--accent); color: var(--accent); }
main { padding: 1.25rem 1.5rem 2rem; max-width: 920px; }
.page { display: none; }
.page.active { display: block; }
label { display: block; margin-bottom: 0.75rem; color: var(--muted); font-size: 0.85rem; }
select, input, textarea {
  display: block;
  width: 100%;
  margin-top: 0.35rem;
  background: rgba(0,0,0,0.35);
  border: 1px solid var(--line);
  color: var(--ink);
  padding: 0.55rem 0.65rem;
  font: inherit;
}
.history {
  height: 320px;
  overflow: auto;
  border: 1px solid var(--line);
  padding: 0.75rem;
  margin-bottom: 0.75rem;
  background: rgba(0,0,0,0.25);
  font-size: 0.88rem;
}
.history .msg { margin: 0 0 0.65rem; }
.history .who { color: var(--accent); font-weight: 600; }
.row { display: flex; gap: 0.5rem; margin-top: 0.65rem; }
button {
  background: var(--btn);
  border: 1px solid var(--line);
  color: var(--ink);
  padding: 0.5rem 0.9rem;
  cursor: pointer;
  font: inherit;
}
button.primary { border-color: var(--accent); color: var(--accent); }
.status {
  margin-top: 0.75rem;
  color: var(--muted);
  font-size: 0.8rem;
  white-space: pre-wrap;
}
code { color: var(--accent); }

const $ = (id) => document.getElementById(id);

document.querySelectorAll(".tab").forEach((btn) => {
  btn.addEventListener("click", () => {
    document.querySelectorAll(".tab").forEach((b) => b.classList.remove("active"));
    document.querySelectorAll(".page").forEach((p) => p.classList.remove("active"));
    btn.classList.add("active");
    $(`page-${btn.dataset.page}`).classList.add("active");
  });
});

function renderHistory(el, messages) {
  el.innerHTML = (messages || [])
    .map(
      (m) =>
        `<div class="msg"><span class="who">${escapeHtml(m.who || "?")}</span>: ${escapeHtml(m.text || "")}</div>`,
    )
    .join("") || "<div class='msg'>(no messages)</div>";
  el.scrollTop = el.scrollHeight;
}

function escapeHtml(s) {
  return String(s)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
}

async function boot() {
  const st = await window.avaDesktop.envStatus();
  $("settings-status").textContent = JSON.stringify(st, null, 2);
  if (st.operatorChatId) $("telegram-chat").value = st.operatorChatId;

  const ch = await window.avaDesktop.listDiscordChannels();
  const sel = $("discord-channel");
  sel.innerHTML = "";
  for (const c of ch.channels || []) {
    const opt = document.createElement("option");
    opt.value = c.id;
    opt.textContent = `#${c.name}`;
    sel.appendChild(opt);
  }
  // Prefer #admins / #updates if present
  const prefer = (ch.channels || []).find((c) =>
    /admins|updates|general/i.test(c.name),
  );
  if (prefer) sel.value = prefer.id;

  await refreshDiscord();
  await refreshTelegram();
}

async function refreshDiscord() {
  const channelId = $("discord-channel").value;
  const hist = await window.avaDesktop.history({ surface: "discord", channelId });
  renderHistory($("discord-history"), hist.messages);
  $("discord-status").textContent = hist.ok
    ? `loaded ${hist.messages?.length || 0} msgs`
    : hist.detail || "fail";
}

async function refreshTelegram() {
  const channelId = $("telegram-chat").value.trim();
  const hist = await window.avaDesktop.history({ surface: "telegram", channelId });
  renderHistory($("telegram-history"), hist.messages);
  $("telegram-status").textContent = `context ${hist.messages?.length || 0} msgs (local ring + send)`;
}

$("discord-refresh").onclick = refreshDiscord;
$("telegram-refresh").onclick = refreshTelegram;
$("discord-channel").onchange = refreshDiscord;

$("discord-send").onclick = async () => {
  const text = $("discord-draft").value.trim();
  if (!text) return;
  $("discord-status").textContent = "rewriting + sending…";
  try {
    const r = await window.avaDesktop.send({
      surface: "discord",
      channelId: $("discord-channel").value,
      text,
    });
    $("discord-draft").value = "";
    $("discord-status").textContent = `sent\nrewritten:\n${r.rewritten}`;
    await refreshDiscord();
  } catch (err) {
    $("discord-status").textContent = String(err.message || err);
  }
};

$("telegram-send").onclick = async () => {
  const text = $("telegram-draft").value.trim();
  if (!text) return;
  $("telegram-status").textContent = "rewriting + sending…";
  try {
    const r = await window.avaDesktop.send({
      surface: "telegram",
      channelId: $("telegram-chat").value.trim(),
      text,
    });
    $("telegram-draft").value = "";
    $("telegram-status").textContent = `sent\nrewritten:\n${r.rewritten}`;
    await refreshTelegram();
  } catch (err) {
    $("telegram-status").textContent = String(err.message || err);
  }
};

boot().catch((err) => {
  $("settings-status").textContent = String(err.message || err);
});

