/**
 * PROP reaction smoke + junk filter unit checks (Post Absolute Ops).
 */
import { loadEnv, botToken, AVA_CHANNELS } from "../src/config.mjs";
import { makeFetchJson } from "../src/discordApi.mjs";
import { seedVoteReactions, VOTE_START_REACTIONS } from "../src/seedVoteReactions.mjs";
import { isJunkAvaPost } from "../src/followupScan.mjs";
import { isChannelCleanupCommand } from "../src/channelCleanup.mjs";
import { postMessage } from "../src/discordApi.mjs";
import { splitContent } from "../src/splitContent.mjs";

const TARGETS = [
  { label: "ava-core forum", channelId: AVA_CHANNELS.proposals, messageId: "1533536738931376400" },
  { label: "ava-core vote", channelId: AVA_CHANNELS.voting, messageId: "1533536743746437163" },
  { label: "website forum", channelId: AVA_CHANNELS.proposals, messageId: "1533536752080523566" },
  { label: "website vote", channelId: AVA_CHANNELS.voting, messageId: "1533536755297292502" },
  { label: "constitution forum", channelId: "1533551413857226913", messageId: "1533551413857226913" },
  { label: "constitution vote", channelId: AVA_CHANNELS.voting, messageId: "1533551416847761499" },
  { label: "majority amend vote", channelId: AVA_CHANNELS.voting, messageId: "1533553302208516177" },
];

function hasAllVoteEmojis(reactions = []) {
  const names = new Set(
    (reactions || []).map((r) => String(r.emoji?.name || r.emoji?.id || "")),
  );
  return VOTE_START_REACTIONS.every((e) => names.has(e));
}

const env = await loadEnv();
const fetchJson = makeFetchJson(botToken(env));

console.log("=== unit filters ===");
const units = {
  junkEmpty: isJunkAvaPost(""),
  junkSign: isJunkAvaPost("— Ava"),
  junkDash: isJunkAvaPost("- Ava"),
  junkOk: !isJunkAvaPost("hey — catching Absolute Ops leftovers."),
  cleanCmd: isChannelCleanupCommand("Would like you to clean though"),
  cleanCmd2: isChannelCleanupCommand("condense this to one post please"),
  splitDropsSignoff: splitContent("hello\n\n— Ava").every((p) => !/^[—\-–]\s*Ava\s*$/i.test(p)),
};
console.log(units);
if (Object.values(units).some((v) => !v)) {
  console.error("UNIT FAIL");
  process.exit(1);
}

// postMessage junk reject (no network if returns null early)
const junkPost = await postMessage(async () => {
  throw new Error("should not fetch");
}, "0", "— Ava", null);
if (junkPost !== null) {
  console.error("postMessage should reject signoff-only");
  process.exit(1);
}
console.log("postMessage junk reject: ok");

console.log("=== PROP reactions ===");
for (const t of TARGETS) {
  try {
    const msg = await fetchJson(
      `/channels/${t.channelId}/messages/${t.messageId}`,
    );
    const ok = hasAllVoteEmojis(msg.reactions);
    console.log(t.label, ok ? "OK" : "MISSING", (msg.reactions || []).map((r) => r.emoji?.name).join(","));
    if (!ok) {
      await seedVoteReactions(fetchJson, t.channelId, t.messageId);
      console.log("  reseeded", t.label);
    }
  } catch (err) {
    console.warn(t.label, "fetch fail", err.message.slice(0, 120));
    try {
      await seedVoteReactions(fetchJson, t.channelId, t.messageId);
      console.log("  reseed attempted", t.label);
    } catch (e2) {
      console.warn("  reseed fail", e2.message.slice(0, 80));
    }
  }
  await new Promise((r) => setTimeout(r, 400));
}

console.log("smoke done");

