/**
 * Reseed still-open PROP / vote messages with vote_yes / vote_no / ➖.
 * Skips archived Slack-dev + hourly-gov + constitution helm (already closed).
 */
import { loadEnv, botToken, AVA_CHANNELS } from "../src/config.mjs";
import { makeFetchJson } from "../src/discordApi.mjs";
import { seedVoteReactions, VOTE_START_REACTIONS } from "../src/seedVoteReactions.mjs";

const CLOSED = new Set([
  "1532933442319155302", // slack-dev
  "1532945550486278175", // hourly gov
  "1533551413857226913", // constitution helm
]);

const env = await loadEnv();
const f = makeFetchJson(botToken(env));
const guildId = "1516108585740800042";

async function clearUnicodeVote(channelId, messageId) {
  for (const emoji of ["✅", "❌"]) {
    try {
      const enc = encodeURIComponent(emoji);
      await f(
        `/channels/${channelId}/messages/${messageId}/reactions/${enc}/@me`,
        { method: "DELETE" },
      );
    } catch {
      // ignore
    }
  }
}

async function reseedMessage(channelId, messageId, label) {
  await clearUnicodeVote(channelId, messageId);
  const ok = await seedVoteReactions(f, channelId, messageId, VOTE_START_REACTIONS);
  console.log(ok ? "reseeded" : "partial", label, channelId, messageId);
}

// Active guild threads under proposals
const active = await f(`/guilds/${guildId}/threads/active`);
const threads = (active.threads || []).filter(
  (t) =>
    t.parent_id === AVA_CHANNELS.proposals &&
    !t.thread_metadata?.archived &&
    !CLOSED.has(t.id),
);

for (const t of threads) {
  // Starter message id == thread id for forum posts
  await reseedMessage(t.id, t.id, t.name);
  // Also recent messages that look like VOTE
  try {
    const msgs = await f(`/channels/${t.id}/messages?limit=15`);
    for (const m of msgs) {
      if (m.id === t.id) continue;
      if (/\*\*\s*VOTE\b|React:\s*|7[- ]?day weighted/i.test(m.content || "")) {
        await reseedMessage(t.id, m.id, `vote-in:${t.name}`);
      }
    }
  } catch (e) {
    console.warn("thread msgs", t.id, e.message);
  }
}

// #voting recent open-looking posts
try {
  const voteMsgs = await f(`/channels/${AVA_CHANNELS.voting}/messages?limit=30`);
  for (const m of voteMsgs) {
    if (!/\*\*\s*(VOTE|PROP)\b|React:|7[- ]?day weighted|Proposal:/i.test(m.content || "")) {
      continue;
    }
    await reseedMessage(AVA_CHANNELS.voting, m.id, "voting");
  }
} catch (e) {
  console.warn("voting", e.message);
}

console.log("done reseeds");

