for (const id of list) {
  try {
    results.push(await silentArchive(f, id));
    console.log("closed", id, results[results.length - 1]);
  } catch (err) {
    console.warn("fail", id, err.message);
    results.push({ id, ok: false, error: err.message });
  }
}

