/**
 * Read-only Stripe finance for Ava (RootMC Pro / membership income).
 * Secrets from RootMC .env via loadEnv — never log raw keys or dump to Discord public.
 */
import fs from "node:fs";
import path from "node:path";
import { storePaths } from "./store.mjs";
import { appendAction } from "./fullLog.mjs";

const STRIPE_API = "https://api.stripe.com/v1";

function financeDir() {
  const dir = path.join(storePaths().dir, "finance");
  fs.mkdirSync(dir, { recursive: true });
  return dir;
}

function snapshotPath() {
  return path.join(financeDir(), "stripe-snapshot.json");
}

export function stripeSecretKey(env = {}) {
  return String(
    process.env.STRIPE_SECRET_KEY || env.STRIPE_SECRET_KEY || "",
  ).trim();
}

export function stripeConfigured(env = {}) {
  return Boolean(stripeSecretKey(env));
}

async function stripeGet(env, route, params = {}) {
  const key = stripeSecretKey(env);
  if (!key) throw new Error("stripe_secret_missing");
  const qs = new URLSearchParams();
  for (const [k, v] of Object.entries(params)) {
    if (v == null || v === "") continue;
    qs.set(k, String(v));
  }
  const url = `${STRIPE_API}${route}${qs.toString() ? `?${qs}` : ""}`;
  const res = await fetch(url, {
    headers: {
      Authorization: `Bearer ${key}`,
      "Stripe-Version": "2024-11-20.acacia",
    },
  });
  const text = await res.text();
  let data;
  try {
    data = JSON.parse(text);
  } catch {
    throw new Error(`stripe_bad_json_${res.status}`);
  }
  if (!res.ok) {
    const msg = data?.error?.message || `stripe_http_${res.status}`;
    throw new Error(msg);
  }
  return data;
}

function centsToUsd(cents) {
  const n = Number(cents) || 0;
  return Math.round(n) / 100;
}

function formatUsd(n) {
  const v = Number(n) || 0;
  return `$${v.toFixed(2)}`;
}

/**
 * Pull Balance + recent balance_transactions; cache snapshot locally.
 */
export async function refreshStripeSnapshot(env = {}, { force = false } = {}) {
  if (!stripeConfigured(env)) {
    return { ok: false, reason: "stripe_not_configured" };
  }

  let prev = null;
  try {
    if (fs.existsSync(snapshotPath())) {
      prev = JSON.parse(fs.readFileSync(snapshotPath(), "utf8"));
    }
  } catch {
    prev = null;
  }

  const maxAgeMs = Number(process.env.AVA_STRIPE_CACHE_MS || 15 * 60 * 1000);
  if (
    !force &&
    prev?.ok &&
    prev.fetchedAt &&
    Date.now() - prev.fetchedAt < maxAgeMs
  ) {
    return prev;
  }

  try {
    const [balance, txs] = await Promise.all([
      stripeGet(env, "/balance"),
      stripeGet(env, "/balance_transactions", {
        limit: "40",
        "expand[]": "data.source",
      }),
    ]);

    const available = (balance.available || []).map((b) => ({
      currency: b.currency,
      amount: centsToUsd(b.amount),
    }));
    const pending = (balance.pending || []).map((b) => ({
      currency: b.currency,
      amount: centsToUsd(b.amount),
    }));

    const usdAvail = available
      .filter((b) => b.currency === "usd")
      .reduce((s, b) => s + b.amount, 0);
    const usdPending = pending
      .filter((b) => b.currency === "usd")
      .reduce((s, b) => s + b.amount, 0);

    let income30d = 0;
    let fee30d = 0;
    let payout30d = 0;
    const cutoff = Date.now() / 1000 - 30 * 86400;
    const recent = [];
    for (const t of txs.data || []) {
      const created = Number(t.created) || 0;
      const amt = centsToUsd(t.amount);
      const fee = centsToUsd(t.fee);
      if (created >= cutoff) {
        if (t.type === "charge" || t.type === "payment" || t.net > 0) {
          if (amt > 0) income30d += amt;
        }
        if (t.type === "payout") payout30d += Math.abs(amt);
        fee30d += Math.abs(fee);
      }
      recent.push({
        id: t.id,
        type: t.type,
        amount: amt,
        fee,
        net: centsToUsd(t.net),
        currency: t.currency,
        created: created * 1000,
        description: String(t.description || "").slice(0, 120),
      });
    }

    const snap = {
      ok: true,
      fetchedAt: Date.now(),
      available,
      pending,
      usdAvailable: usdAvail,
      usdPending: usdPending,
      income30dUsd: Math.round(income30d * 100) / 100,
      fees30dUsd: Math.round(fee30d * 100) / 100,
      payouts30dUsd: Math.round(payout30d * 100) / 100,
      recent: recent.slice(0, 25),
      source: "stripe_balance_api",
    };
    fs.writeFileSync(snapshotPath(), JSON.stringify(snap, null, 2), "utf8");
    appendAction("stripeFinance.refresh", {
      usdAvailable: snap.usdAvailable,
      income30dUsd: snap.income30dUsd,
    });
    return snap;
  } catch (err) {
    const fail = {
      ok: false,
      reason: err.message || "stripe_error",
      fetchedAt: Date.now(),
      previous: prev?.ok ? { usdAvailable: prev.usdAvailable, income30dUsd: prev.income30dUsd } : null,
    };
    appendAction("stripeFinance.error", { reason: fail.reason });
    return fail;
  }
}

export function loadStripeSnapshot() {
  try {
    if (!fs.existsSync(snapshotPath())) return null;
    return JSON.parse(fs.readFileSync(snapshotPath(), "utf8"));
  } catch {
    return null;
  }
}

/** Human-readable summary for operator asks (Telegram / Slack / DM). */
export function formatStripeIncomePlain(snap) {
  if (!snap?.ok) {
    return snap?.reason
      ? `Stripe read unavailable (${snap.reason}).`
      : "Stripe not configured yet.";
  }
  const ageMin = Math.round((Date.now() - (snap.fetchedAt || 0)) / 60000);
  return [
    `Stripe available: ${formatUsd(snap.usdAvailable)} (pending ${formatUsd(snap.usdPending)})`,
    `~30d gross credits: ${formatUsd(snap.income30dUsd)} · fees ~${formatUsd(snap.fees30dUsd)} · payouts ~${formatUsd(snap.payouts30dUsd)}`,
    `Snapshot age: ${ageMin}m`,
  ].join("\n");
}

export { formatUsd, centsToUsd, financeDir };

/**
 * Ava ops finance ledger — other income sources + expenses (manual + suggested).
 * Isolated from player Gold (G). Real-money tracking only.
 */
import fs from "node:fs";
import path from "node:path";
import { financeDir, formatUsd } from "./stripeFinance.mjs";
import { appendAction } from "./fullLog.mjs";

function ledgerPath() {
  return path.join(financeDir(), "ops-ledger.json");
}

const DEFAULT_LEDGER = {
  updatedAt: null,
  currency: "USD",
  otherIncome: [
    // { id, label, amountUsd, period: "month"|"year"|"once", updatedAt, note }
  ],
  expenses: [
    // { id, label, amountUsd, period, category, updatedAt, note }
  ],
  lastSuggestionAt: null,
  lastSuggestions: [],
};

export function loadOpsLedger() {
  try {
    if (!fs.existsSync(ledgerPath())) {
      const seed = {
        ...DEFAULT_LEDGER,
        updatedAt: Date.now(),
        expenses: [
          {
            id: "exp-shockbyte",
            label: "Shockbyte hosting (Claims+Towny)",
            amountUsd: 0,
            period: "month",
            category: "ops",
            updatedAt: null,
            note: "Set real monthly total when known",
          },
          {
            id: "exp-domains",
            label: "Domains (rootmc.net + related)",
            amountUsd: 0,
            period: "year",
            category: "ops",
            updatedAt: null,
            note: "Annual — convert to monthly when reviewing",
          },
          {
            id: "exp-cloudflare",
            label: "Cloudflare / Workers / Pages",
            amountUsd: 0,
            period: "month",
            category: "dev",
            updatedAt: null,
            note: "Include paid add-ons if any",
          },
        ],
        otherIncome: [
          {
            id: "inc-other",
            label: "Other (ads, sponsors, one-offs)",
            amountUsd: 0,
            period: "month",
            updatedAt: null,
            note: "Non-Stripe income — update when known",
          },
        ],
      };
      saveOpsLedger(seed);
      return seed;
    }
    return JSON.parse(fs.readFileSync(ledgerPath(), "utf8"));
  } catch {
    return { ...DEFAULT_LEDGER, otherIncome: [], expenses: [] };
  }
}

export function saveOpsLedger(ledger) {
  const next = { ...ledger, updatedAt: Date.now() };
  fs.writeFileSync(ledgerPath(), JSON.stringify(next, null, 2), "utf8");
  return next;
}

function monthlyize(amountUsd, period) {
  const a = Number(amountUsd) || 0;
  switch (String(period || "month")) {
    case "year":
      return a / 12;
    case "week":
      return (a * 52) / 12;
    case "once":
      return 0;
    default:
      return a;
  }
}

export function summarizeOpsLedger(ledger = loadOpsLedger()) {
  const incomeM = (ledger.otherIncome || []).reduce(
    (s, r) => s + monthlyize(r.amountUsd, r.period),
    0,
  );
  const expenseM = (ledger.expenses || []).reduce(
    (s, r) => s + monthlyize(r.amountUsd, r.period),
    0,
  );
  const stale = [];
  const staleMs = 45 * 86400 * 1000;
  for (const row of [...(ledger.otherIncome || []), ...(ledger.expenses || [])]) {
    if (!row.updatedAt || Date.now() - row.updatedAt > staleMs) {
      stale.push(row.id || row.label);
    }
  }
  return {
    otherIncomeMonthlyUsd: Math.round(incomeM * 100) / 100,
    expensesMonthlyUsd: Math.round(expenseM * 100) / 100,
    netOtherMonthlyUsd: Math.round((incomeM - expenseM) * 100) / 100,
    staleIds: stale,
    expenseCount: (ledger.expenses || []).length,
    incomeCount: (ledger.otherIncome || []).length,
  };
}

export function upsertOpsExpense({
  id,
  label,
  amountUsd,
  period = "month",
  category = "ops",
  note = "",
} = {}) {
  const ledger = loadOpsLedger();
  const rid =
    id ||
    `exp-${String(label || "item")
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, "-")
      .slice(0, 40)}`;
  const rows = Array.isArray(ledger.expenses) ? [...ledger.expenses] : [];
  const idx = rows.findIndex((r) => r.id === rid);
  const row = {
    id: rid,
    label: label || rid,
    amountUsd: Number(amountUsd) || 0,
    period,
    category,
    note: note || "",
    updatedAt: Date.now(),
  };
  if (idx >= 0) rows[idx] = { ...rows[idx], ...row };
  else rows.push(row);
  ledger.expenses = rows;
  saveOpsLedger(ledger);
  appendAction("opsFinance.expenseUpsert", { id: rid, amountUsd: row.amountUsd });
  return row;
}

export function upsertOpsIncome({
  id,
  label,
  amountUsd,
  period = "month",
  note = "",
} = {}) {
  const ledger = loadOpsLedger();
  const rid =
    id ||
    `inc-${String(label || "item")
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, "-")
      .slice(0, 40)}`;
  const rows = Array.isArray(ledger.otherIncome) ? [...ledger.otherIncome] : [];
  const idx = rows.findIndex((r) => r.id === rid);
  const row = {
    id: rid,
    label: label || rid,
    amountUsd: Number(amountUsd) || 0,
    period,
    note: note || "",
    updatedAt: Date.now(),
  };
  if (idx >= 0) rows[idx] = { ...rows[idx], ...row };
  else rows.push(row);
  ledger.otherIncome = rows;
  saveOpsLedger(ledger);
  appendAction("opsFinance.incomeUpsert", { id: rid, amountUsd: row.amountUsd });
  return row;
}

export function formatOpsLedgerPlain(ledger = loadOpsLedger()) {
  const sum = summarizeOpsLedger(ledger);
  const expLines = (ledger.expenses || [])
    .slice(0, 12)
    .map(
      (e) =>
        `- ${e.label}: ${formatUsd(e.amountUsd)}/${e.period || "mo"} [${e.category || "?"}]`,
    )
    .join("\n");
  const incLines = (ledger.otherIncome || [])
    .slice(0, 8)
    .map((e) => `- ${e.label}: ${formatUsd(e.amountUsd)}/${e.period || "mo"}`)
    .join("\n");
  return [
    `Ops expenses (~monthly): ${formatUsd(sum.expensesMonthlyUsd)}`,
    expLines || "- (none yet)",
    `Other income (~monthly): ${formatUsd(sum.otherIncomeMonthlyUsd)}`,
    incLines || "- (none yet)",
    sum.staleIds.length
      ? `Stale / never updated: ${sum.staleIds.slice(0, 8).join(", ")}`
      : "All ledger rows recently touched.",
  ].join("\n");
}

/**
 * Per-player finance tracking — opt-in only, isolated on Discord profile.
 * Never mixes with in-game Gold (G) or Ava ops Stripe ledger.
 */
import { loadPlayerProfile, savePlayerProfileMut } from "./playerProfiles.mjs";
import { personByAuthorId, personByDiscordId } from "./people.mjs";
import { formatUsd } from "./stripeFinance.mjs";
import { appendAction } from "./fullLog.mjs";

function emptyFinance() {
  return {
    optIn: false,
    optInAt: null,
    optOutAt: null,
    currency: "USD",
    income: [],
    expenses: [],
    notes: [],
    lastReviewAt: null,
  };
}

export function getPlayerFinance(discordId) {
  const p = loadPlayerProfile(discordId);
  if (!p?.finance) return emptyFinance();
  return { ...emptyFinance(), ...p.finance };
}

export function setPlayerFinanceOptIn(discordId, optIn, { username } = {}) {
  const id = String(discordId || "");
  if (!id) return null;
  return savePlayerProfileMut(id, (p) => {
    if (username) p.username = username;
    const fin = { ...emptyFinance(), ...(p.finance || {}) };
    fin.optIn = Boolean(optIn);
    if (optIn) {
      fin.optInAt = Date.now();
      fin.optOutAt = null;
    } else {
      fin.optOutAt = Date.now();
    }
    p.finance = fin;
    return p;
  });
}

function monthlyize(amountUsd, period) {
  const a = Number(amountUsd) || 0;
  switch (String(period || "month")) {
    case "year":
      return a / 12;
    case "week":
      return (a * 52) / 12;
    case "once":
      return 0;
    default:
      return a;
  }
}

export function summarizePlayerFinance(fin) {
  const incomeM = (fin.income || []).reduce(
    (s, r) => s + monthlyize(r.amountUsd, r.period),
    0,
  );
  const expenseM = (fin.expenses || []).reduce(
    (s, r) => s + monthlyize(r.amountUsd, r.period),
    0,
  );
  return {
    incomeMonthlyUsd: Math.round(incomeM * 100) / 100,
    expensesMonthlyUsd: Math.round(expenseM * 100) / 100,
    netMonthlyUsd: Math.round((incomeM - expenseM) * 100) / 100,
  };
}

export function upsertPlayerLine(
  discordId,
  kind,
  { label, amountUsd, period = "month", note = "" } = {},
) {
  const id = String(discordId || "");
  if (!id) return { ok: false, reason: "no_id" };
  const profile = savePlayerProfileMut(id, (p) => {
    const fin = { ...emptyFinance(), ...(p.finance || {}) };
    if (!fin.optIn) {
      p._financeErr = "not_opted_in";
      return p;
    }
    const listKey = kind === "income" ? "income" : "expenses";
    const rows = Array.isArray(fin[listKey]) ? [...fin[listKey]] : [];
    const rid = `${kind}-${String(label || "item")
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, "-")
      .slice(0, 40)}`;
    const idx = rows.findIndex((r) => r.id === rid || r.label === label);
    const row = {
      id: rid,
      label: label || rid,
      amountUsd: Number(amountUsd) || 0,
      period,
      note: note || "",
      updatedAt: Date.now(),
    };
    if (idx >= 0) rows[idx] = { ...rows[idx], ...row };
    else rows.push(row);
    fin[listKey] = rows;
    p.finance = fin;
    delete p._financeErr;
    return p;
  });
  if (profile?._financeErr) {
    return { ok: false, reason: profile._financeErr };
  }
  appendAction("playerFinance.upsert", {
    discordId: id,
    kind,
    label,
    amountUsd: Number(amountUsd) || 0,
  });
  return { ok: true, finance: profile.finance };
}

export function formatPlayerFinancePlain(discordId) {
  const fin = getPlayerFinance(discordId);
  if (!fin.optIn) {
    return "Personal finance tracking is off for you. Say “track my finances” to opt in (isolated to your profile — not shared).";
  }
  const sum = summarizePlayerFinance(fin);
  const inc = (fin.income || [])
    .map((r) => `- ${r.label}: ${formatUsd(r.amountUsd)}/${r.period || "mo"}`)
    .join("\n");
  const exp = (fin.expenses || [])
    .map((r) => `- ${r.label}: ${formatUsd(r.amountUsd)}/${r.period || "mo"}`)
    .join("\n");
  return [
    `Your tracked finances (private to your profile):`,
    `Income ~${formatUsd(sum.incomeMonthlyUsd)}/mo`,
    inc || "- (add with: add income rent-job 2000/mo)",
    `Expenses ~${formatUsd(sum.expensesMonthlyUsd)}/mo`,
    exp || "- (add with: add expense rent 1200/mo)",
    `Net ~${formatUsd(sum.netMonthlyUsd)}/mo`,
  ].join("\n");
}

export function isOperatorAuthor(authorId, authorName) {
  const p =
    personByAuthorId(authorId, authorName) || personByDiscordId(authorId);
  return Boolean(p?.roles?.includes("owner") || p?.id === "alexrs94");
}

/**
 * Structured finance commands — returns reply text or null.
 */
export function tryHandleFinanceCommand({
  text = "",
  authorId,
  authorName,
  surface = "discord",
} = {}) {
  const q = String(text || "").trim();
  if (!q) return null;
  const lower = q.toLowerCase();

  // Player opt-in / out
  if (
    /\b(track\s+my\s+finances?|start\s+tracking\s+my\s+(money|finances?|expenses?)|opt\s*in\s+(to\s+)?finance)\b/i.test(
      lower,
    )
  ) {
    setPlayerFinanceOptIn(authorId, true, { username: authorName });
    return {
      handled: true,
      reply:
        "Got it — I'll track your finances on your profile only (income + expenses you give me). Not shared with other players, not mixed with server Gold. Say “my finances” anytime, or “stop tracking my finances” to opt out. Add lines like: add expense rent 1200/mo · add income job 2500/mo",
    };
  }
  if (
    /\b(stop\s+tracking\s+my\s+finances?|opt\s*out\s+(of\s+)?finance|don'?t\s+track\s+my\s+(money|finances?))\b/i.test(
      lower,
    )
  ) {
    setPlayerFinanceOptIn(authorId, false, { username: authorName });
    return {
      handled: true,
      reply:
        "Personal finance tracking off for you. Prior numbers stay on your profile but I won't update or brief them unless you opt back in.",
    };
  }
  if (
    /\b(my\s+finances?|show\s+my\s+(expenses?|income|finances?)|what('?s|\s+is)\s+my\s+(burn|budget))\b/i.test(
      lower,
    )
  ) {
    return { handled: true, reply: formatPlayerFinancePlain(authorId) };
  }

  const addPlayer = q.match(
    /^\s*(?:ava[,:]?\s*)?(?:please\s+)?add\s+(expense|income)\s+(.+?)\s+(\d+(?:\.\d+)?)\s*(?:\/|\s+per\s+)?(mo(?:nth)?|yr|year|week|once)?\s*$/i,
  );
  if (addPlayer) {
    const kind = addPlayer[1].toLowerCase();
    const label = addPlayer[2].trim();
    const amountUsd = Number(addPlayer[3]);
    const periodRaw = (addPlayer[4] || "month").toLowerCase();
    const period = periodRaw.startsWith("y")
      ? "year"
      : periodRaw.startsWith("w")
        ? "week"
        : periodRaw === "once"
          ? "once"
          : "month";
    const r = upsertPlayerLine(authorId, kind, { label, amountUsd, period });
    if (!r.ok) {
      return {
        handled: true,
        reply:
          "Opt in first with “track my finances” — then I can add that line on your private profile.",
      };
    }
    return {
      handled: true,
      reply: `Logged ${kind} “${label}” at ${formatUsd(amountUsd)}/${period} on your private profile.\n${formatPlayerFinancePlain(authorId)}`,
    };
  }

  // Operator ops ledger (Alex only)
  if (!isOperatorAuthor(authorId, authorName)) return null;

  const addOps = q.match(
    /^\s*(?:ava[,:]?\s*)?(?:please\s+)?(?:ops\s+)?add\s+ops\s+(expense|income)\s+(.+?)\s+(\d+(?:\.\d+)?)\s*(?:\/|\s+per\s+)?(mo(?:nth)?|yr|year|week|once)?\s*$/i,
  );
  if (addOps) {
    const { upsertOpsExpense, upsertOpsIncome, formatOpsLedgerPlain } =
      // lazy to avoid cycles
      requireOps();
    const kind = addOps[1].toLowerCase();
    const label = addOps[2].trim();
    const amountUsd = Number(addOps[3]);
    const periodRaw = (addOps[4] || "month").toLowerCase();
    const period = periodRaw.startsWith("y")
      ? "year"
      : periodRaw.startsWith("w")
        ? "week"
        : periodRaw === "once"
          ? "once"
          : "month";
    if (kind === "income") upsertOpsIncome({ label, amountUsd, period });
    else upsertOpsExpense({ label, amountUsd, period });
    return {
      handled: true,
      reply: `Ops ${kind} logged.\n${formatOpsLedgerPlain()}`,
    };
  }

  return null;
}

function requireOps() {
  return {
    upsertOpsExpense: (...a) =>
      import("./opsFinanceLedger.mjs").then((m) => m.upsertOpsExpense(...a)),
    // sync path — use dynamic import sync via createRequire alternative: just import at top
  };
}

