/**
 * Shared multi-account finance model for players + projects (Ava, RootMC ops, …).
 * Each owner can hold many accounts: cash/income streams, debts, credit, Stripe, etc.
 */
import { formatUsd } from "./stripeFinance.mjs";

export function slugId(prefix, label) {
  const s = String(label || "item")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "")
    .slice(0, 40);
  return `${prefix}-${s || "item"}`;
}

export function emptyAccount({
  id,
  name = "Default",
  kind = "cash",
  currency = "USD",
  note = "",
} = {}) {
  return {
    id: id || slugId("acct", name),
    name,
    kind, // cash | bank | stripe | income | debt | credit | project | other
    currency,
    balanceUsd: 0,
    income: [],
    expenses: [],
    debts: [], // { id, label, balanceUsd, apr, minimumUsd, period, note, updatedAt }
    note,
    createdAt: Date.now(),
    updatedAt: Date.now(),
  };
}

export function emptyProject({ id, name, note = "" } = {}) {
  return {
    id: id || slugId("proj", name || "project"),
    name: name || id || "Project",
    note,
    accounts: [emptyAccount({ id: "acct-default", name: "Default", kind: "cash" })],
    updatedAt: Date.now(),
  };
}

function monthlyize(amountUsd, period) {
  const a = Number(amountUsd) || 0;
  switch (String(period || "month")) {
    case "year":
      return a / 12;
    case "week":
      return (a * 52) / 12;
    case "once":
      return 0;
    default:
      return a;
  }
}

export function summarizeAccount(acct) {
  const incomeM = (acct.income || []).reduce(
    (s, r) => s + monthlyize(r.amountUsd, r.period),
    0,
  );
  const expenseM = (acct.expenses || []).reduce(
    (s, r) => s + monthlyize(r.amountUsd, r.period),
    0,
  );
  const debtBal = (acct.debts || []).reduce(
    (s, r) => s + (Number(r.balanceUsd) || 0),
    0,
  );
  // Debt-kind account: balanceUsd itself is owed
  const kindDebt =
    acct.kind === "debt" || acct.kind === "credit"
      ? Number(acct.balanceUsd) || 0
      : 0;
  return {
    incomeMonthlyUsd: Math.round(incomeM * 100) / 100,
    expensesMonthlyUsd: Math.round(expenseM * 100) / 100,
    netMonthlyUsd: Math.round((incomeM - expenseM) * 100) / 100,
    balanceUsd: Number(acct.balanceUsd) || 0,
    debtBalanceUsd: Math.round((debtBal + kindDebt) * 100) / 100,
  };
}

export function summarizeAccounts(accounts = []) {
  let incomeM = 0;
  let expenseM = 0;
  let balance = 0;
  let debt = 0;
  for (const a of accounts) {
    const s = summarizeAccount(a);
    incomeM += s.incomeMonthlyUsd;
    expenseM += s.expensesMonthlyUsd;
    if (a.kind === "debt" || a.kind === "credit") debt += s.balanceUsd;
    else balance += s.balanceUsd;
    debt += (a.debts || []).reduce((x, d) => x + (Number(d.balanceUsd) || 0), 0);
  }
  return {
    accountCount: accounts.length,
    incomeMonthlyUsd: Math.round(incomeM * 100) / 100,
    expensesMonthlyUsd: Math.round(expenseM * 100) / 100,
    netMonthlyUsd: Math.round((incomeM - expenseM) * 100) / 100,
    balanceUsd: Math.round(balance * 100) / 100,
    debtBalanceUsd: Math.round(debt * 100) / 100,
  };
}

export function findAccount(accounts, nameOrId) {
  const key = String(nameOrId || "")
    .trim()
    .toLowerCase();
  if (!key) return null;
  return (
    (accounts || []).find(
      (a) =>
        a.id === key ||
        a.id === `acct-${key}` ||
        String(a.name || "").toLowerCase() === key,
    ) || null
  );
}

export function ensureAccount(accounts, nameOrId, { kind = "cash", create = true } = {}) {
  const list = Array.isArray(accounts) ? [...accounts] : [];
  let acct = findAccount(list, nameOrId);
  if (acct) return { accounts: list, account: acct, created: false };
  if (!create) return { accounts: list, account: null, created: false };
  const name = String(nameOrId || "Default").trim() || "Default";
  acct = emptyAccount({ name, kind });
  list.push(acct);
  return { accounts: list, account: acct, created: true };
}

export function upsertLineOnAccount(account, kind, { label, amountUsd, period = "month", note = "" } = {}) {
  const listKey =
    kind === "income" ? "income" : kind === "debt" ? "debts" : "expenses";
  const rows = Array.isArray(account[listKey]) ? [...account[listKey]] : [];
  const rid = slugId(kind === "debt" ? "debt" : kind.slice(0, 3), label);
  const idx = rows.findIndex((r) => r.id === rid || r.label === label);
  const row =
    kind === "debt"
      ? {
          id: rid,
          label: label || rid,
          balanceUsd: Number(amountUsd) || 0,
          apr: null,
          minimumUsd: null,
          period: period || "once",
          note: note || "",
          updatedAt: Date.now(),
        }
      : {
          id: rid,
          label: label || rid,
          amountUsd: Number(amountUsd) || 0,
          period,
          note: note || "",
          updatedAt: Date.now(),
        };
  if (idx >= 0) rows[idx] = { ...rows[idx], ...row };
  else rows.push(row);
  account[listKey] = rows;
  account.updatedAt = Date.now();
  return row;
}

export function setAccountBalance(account, balanceUsd, { note } = {}) {
  account.balanceUsd = Number(balanceUsd) || 0;
  if (note != null) account.note = note;
  account.updatedAt = Date.now();
  return account;
}

/** Migrate flat income/expenses (+ optional debts) into accounts[]. */
export function migrateFlatToAccounts(fin) {
  const next = { ...fin };
  if (Array.isArray(next.accounts) && next.accounts.length) {
    return next;
  }
  const acct = emptyAccount({
    id: "acct-default",
    name: "Default",
    kind: "cash",
  });
  if (Array.isArray(next.income) && next.income.length) {
    acct.income = next.income;
  }
  if (Array.isArray(next.expenses) && next.expenses.length) {
    acct.expenses = next.expenses;
  }
  if (Array.isArray(next.debts) && next.debts.length) {
    acct.debts = next.debts;
  }
  next.accounts = [acct];
  // keep legacy arrays as mirrors of default for older readers
  next.income = acct.income;
  next.expenses = acct.expenses;
  next.debts = acct.debts;
  return next;
}

export function syncLegacyFlatFromAccounts(fin) {
  const accounts = fin.accounts || [];
  const def =
    findAccount(accounts, "default") ||
    findAccount(accounts, "acct-default") ||
    accounts[0];
  if (!def) {
    fin.income = fin.income || [];
    fin.expenses = fin.expenses || [];
    fin.debts = fin.debts || [];
    return fin;
  }
  fin.income = def.income || [];
  fin.expenses = def.expenses || [];
  fin.debts = def.debts || [];
  return fin;
}

export function formatAccountsPlain(accounts, { title = "Accounts" } = {}) {
  const sum = summarizeAccounts(accounts);
  const lines = [
    `${title} (${sum.accountCount}): bal ${formatUsd(sum.balanceUsd)} · debts ${formatUsd(sum.debtBalanceUsd)} · ~income ${formatUsd(sum.incomeMonthlyUsd)}/mo · ~exp ${formatUsd(sum.expensesMonthlyUsd)}/mo · net ${formatUsd(sum.netMonthlyUsd)}/mo`,
  ];
  for (const a of accounts || []) {
    const s = summarizeAccount(a);
    lines.push(
      `• [${a.kind}] ${a.name} (${a.id}): bal ${formatUsd(s.balanceUsd)} · debt ${formatUsd(s.debtBalanceUsd)} · inc ${formatUsd(s.incomeMonthlyUsd)}/mo · exp ${formatUsd(s.expensesMonthlyUsd)}/mo`,
    );
    for (const d of (a.debts || []).slice(0, 6)) {
      lines.push(`    - debt ${d.label}: ${formatUsd(d.balanceUsd)}`);
    }
    for (const r of (a.income || []).slice(0, 4)) {
      lines.push(
        `    - income ${r.label}: ${formatUsd(r.amountUsd)}/${r.period || "mo"}`,
      );
    }
    for (const r of (a.expenses || []).slice(0, 4)) {
      lines.push(
        `    - expense ${r.label}: ${formatUsd(r.amountUsd)}/${r.period || "mo"}`,
      );
    }
  }
  return lines.join("\n");
}

export function parsePeriod(raw) {
  const periodRaw = String(raw || "month").toLowerCase();
  if (periodRaw.startsWith("y")) return "year";
  if (periodRaw.startsWith("w")) return "week";
  if (periodRaw === "once") return "once";
  return "month";
}

/**
 * Project finance ledgers — Ava, RootMC ops, etc. Each project has multiple accounts
 * (cash, Stripe, debts, income streams). Isolated from player Gold (G).
 */
import fs from "node:fs";
import path from "node:path";
import { financeDir, formatUsd } from "./stripeFinance.mjs";
import { appendAction } from "./fullLog.mjs";
import {
  emptyAccount,
  emptyProject,
  ensureAccount,
  findAccount,
  formatAccountsPlain,
  migrateFlatToAccounts,
  parsePeriod,
  slugId,
  summarizeAccounts,
  syncLegacyFlatFromAccounts,
  upsertLineOnAccount,
  setAccountBalance,
} from "./financeAccounts.mjs";

function ledgerPath() {
  return path.join(financeDir(), "ops-ledger.json");
}

function seedProjects() {
  const rootmc = emptyProject({
    id: "rootmc-ops",
    name: "RootMC ops",
    note: "Hosting, domains, CF, Pro funnel costs",
  });
  const def = rootmc.accounts[0];
  def.expenses = [
    {
      id: "exp-shockbyte",
      label: "Shockbyte hosting (Claims+Towny)",
      amountUsd: 0,
      period: "month",
      category: "ops",
      updatedAt: null,
      note: "Set real monthly total when known",
    },
    {
      id: "exp-domains",
      label: "Domains (rootmc.net + related)",
      amountUsd: 0,
      period: "year",
      category: "ops",
      updatedAt: null,
      note: "Annual — convert to monthly when reviewing",
    },
    {
      id: "exp-cloudflare",
      label: "Cloudflare / Workers / Pages",
      amountUsd: 0,
      period: "month",
      category: "dev",
      updatedAt: null,
      note: "Include paid add-ons if any",
    },
  ];
  def.income = [
    {
      id: "inc-other",
      label: "Other (ads, sponsors, one-offs)",
      amountUsd: 0,
      period: "month",
      updatedAt: null,
      note: "Non-Stripe income — update when known",
    },
  ];
  rootmc.accounts.push(
    emptyAccount({
      id: "acct-stripe",
      name: "Stripe",
      kind: "stripe",
      note: "Mirrored from Stripe API snapshots — balance updates via review",
    }),
  );

  const ava = emptyProject({
    id: "ava",
    name: "Ava",
    note: "Ava allocation / hardware wishlist / experiments (10–15% slice)",
  });
  ava.accounts.push(
    emptyAccount({
      id: "acct-wishlist",
      name: "Hardware wishlist",
      kind: "project",
      note: "990 PRO, RTX laptop, etc.",
    }),
  );
  ava.accounts.push(
    emptyAccount({
      id: "acct-debts",
      name: "Debts",
      kind: "debt",
      note: "Ava/project debts owed",
    }),
  );

  return [rootmc, ava];
}

/** Normalize any on-disk shape → projects[] with accounts[]. */
export function normalizeOpsLedger(raw) {
  let ledger = raw && typeof raw === "object" ? { ...raw } : {};
  ledger.currency = ledger.currency || "USD";

  if (!Array.isArray(ledger.projects) || !ledger.projects.length) {
    // Migrate flat otherIncome/expenses into rootmc-ops
    const flat = migrateFlatToAccounts({
      income: ledger.otherIncome || [],
      expenses: ledger.expenses || [],
      debts: ledger.debts || [],
    });
    const rootmc = emptyProject({
      id: "rootmc-ops",
      name: "RootMC ops",
    });
    rootmc.accounts = flat.accounts;
    syncLegacyFlatFromAccounts(rootmc);
    const ava = emptyProject({ id: "ava", name: "Ava" });
    ava.accounts.push(
      emptyAccount({ id: "acct-wishlist", name: "Hardware wishlist", kind: "project" }),
    );
    ava.accounts.push(
      emptyAccount({ id: "acct-debts", name: "Debts", kind: "debt" }),
    );
    ledger.projects = [rootmc, ava];
  }

  ledger.projects = ledger.projects.map((p) => {
    const proj = {
      ...emptyProject({ id: p.id, name: p.name, note: p.note }),
      ...p,
    };
    const migrated = migrateFlatToAccounts({
      income: p.income || p.otherIncome || [],
      expenses: p.expenses || [],
      debts: p.debts || [],
      accounts: p.accounts,
    });
    proj.accounts = migrated.accounts;
    syncLegacyFlatFromAccounts(proj);
    return proj;
  });

  // Mirror first project default onto legacy top-level for old readers
  const primary =
    findProject(ledger.projects, "rootmc-ops") || ledger.projects[0];
  if (primary) {
    const def =
      findAccount(primary.accounts, "default") || primary.accounts[0];
    ledger.otherIncome = def?.income || [];
    ledger.expenses = def?.expenses || [];
    ledger.debts = def?.debts || [];
  }

  return ledger;
}

export function findProject(projects, nameOrId) {
  const key = String(nameOrId || "")
    .trim()
    .toLowerCase();
  if (!key) return null;
  return (
    (projects || []).find(
      (p) =>
        p.id === key ||
        p.id === `proj-${key}` ||
        String(p.name || "").toLowerCase() === key ||
        (key === "ops" && p.id === "rootmc-ops"),
    ) || null
  );
}

export function loadOpsLedger() {
  try {
    if (!fs.existsSync(ledgerPath())) {
      const seed = {
        updatedAt: Date.now(),
        currency: "USD",
        projects: seedProjects(),
        lastSuggestionAt: null,
        lastSuggestions: [],
      };
      const norm = normalizeOpsLedger(seed);
      saveOpsLedger(norm);
      return norm;
    }
    const raw = JSON.parse(fs.readFileSync(ledgerPath(), "utf8"));
    return normalizeOpsLedger(raw);
  } catch {
    return normalizeOpsLedger({
      projects: seedProjects(),
      otherIncome: [],
      expenses: [],
    });
  }
}

export function saveOpsLedger(ledger) {
  const next = normalizeOpsLedger({ ...ledger, updatedAt: Date.now() });
  fs.writeFileSync(ledgerPath(), JSON.stringify(next, null, 2), "utf8");
  return next;
}

export function ensureProject(projectId, { name } = {}) {
  const ledger = loadOpsLedger();
  let proj = findProject(ledger.projects, projectId);
  if (!proj) {
    proj = emptyProject({
      id: slugId("proj", projectId || name || "project").replace(/^proj-proj-/, "proj-"),
      name: name || projectId || "Project",
    });
    // fix id if slug doubled
    if (projectId && !projectId.startsWith("proj-")) {
      proj.id = String(projectId)
        .toLowerCase()
        .replace(/[^a-z0-9-]+/g, "-");
    }
    ledger.projects.push(proj);
    saveOpsLedger(ledger);
  }
  return { ledger: loadOpsLedger(), project: findProject(loadOpsLedger().projects, proj.id) };
}

export function summarizeOpsLedger(ledger = loadOpsLedger()) {
  const projects = ledger.projects || [];
  let incomeM = 0;
  let expenseM = 0;
  let debt = 0;
  let balance = 0;
  const stale = [];
  const staleMs = 45 * 86400 * 1000;

  for (const p of projects) {
    const s = summarizeAccounts(p.accounts || []);
    incomeM += s.incomeMonthlyUsd;
    expenseM += s.expensesMonthlyUsd;
    debt += s.debtBalanceUsd;
    balance += s.balanceUsd;
    for (const a of p.accounts || []) {
      for (const row of [
        ...(a.income || []),
        ...(a.expenses || []),
        ...(a.debts || []),
      ]) {
        if (!row.updatedAt || Date.now() - row.updatedAt > staleMs) {
          stale.push(`${p.id}/${a.id}/${row.id || row.label}`);
        }
      }
    }
  }

  return {
    otherIncomeMonthlyUsd: Math.round(incomeM * 100) / 100,
    expensesMonthlyUsd: Math.round(expenseM * 100) / 100,
    netOtherMonthlyUsd: Math.round((incomeM - expenseM) * 100) / 100,
    debtBalanceUsd: Math.round(debt * 100) / 100,
    balanceUsd: Math.round(balance * 100) / 100,
    projectCount: projects.length,
    accountCount: projects.reduce((n, p) => n + (p.accounts || []).length, 0),
    staleIds: stale,
    expenseCount: projects.reduce(
      (n, p) =>
        n +
        (p.accounts || []).reduce((m, a) => m + (a.expenses || []).length, 0),
      0,
    ),
    incomeCount: projects.reduce(
      (n, p) =>
        n +
        (p.accounts || []).reduce((m, a) => m + (a.income || []).length, 0),
      0,
    ),
  };
}

function mutateProjectAccount(projectId, accountName, mutator) {
  const ledger = loadOpsLedger();
  let proj = findProject(ledger.projects, projectId);
  if (!proj) {
    const created = emptyProject({
      id: String(projectId || "project")
        .toLowerCase()
        .replace(/[^a-z0-9-]+/g, "-"),
      name: projectId || "Project",
    });
    ledger.projects.push(created);
    proj = created;
  }
  const ens = ensureAccount(proj.accounts, accountName || "default", {
    kind: "cash",
    create: true,
  });
  proj.accounts = ens.accounts;
  const acct = ens.account;
  mutator(acct, proj);
  syncLegacyFlatFromAccounts(proj);
  const idx = ledger.projects.findIndex((p) => p.id === proj.id);
  ledger.projects[idx] = proj;
  saveOpsLedger(ledger);
  return { project: proj, account: acct };
}

/** @deprecated flat helper — writes to rootmc-ops / default account */
export function upsertOpsExpense({
  id,
  label,
  amountUsd,
  period = "month",
  category = "ops",
  note = "",
  projectId = "rootmc-ops",
  account = "default",
} = {}) {
  const { account: acct } = mutateProjectAccount(projectId, account, (a) => {
    const row = upsertLineOnAccount(a, "expense", {
      label: label || id,
      amountUsd,
      period,
      note,
    });
    if (category) {
      const list = a.expenses || [];
      const hit = list.find((r) => r.id === row.id);
      if (hit) hit.category = category;
    }
  });
  appendAction("opsFinance.expenseUpsert", {
    projectId,
    account: acct.id,
    label,
    amountUsd: Number(amountUsd) || 0,
  });
  return acct;
}

export function upsertOpsIncome({
  id,
  label,
  amountUsd,
  period = "month",
  note = "",
  projectId = "rootmc-ops",
  account = "default",
} = {}) {
  const { account: acct } = mutateProjectAccount(projectId, account, (a) => {
    upsertLineOnAccount(a, "income", {
      label: label || id,
      amountUsd,
      period,
      note,
    });
  });
  appendAction("opsFinance.incomeUpsert", {
    projectId,
    account: acct.id,
    label,
    amountUsd: Number(amountUsd) || 0,
  });
  return acct;
}

export function upsertOpsDebt({
  label,
  balanceUsd,
  projectId = "ava",
  account = "debts",
  note = "",
} = {}) {
  const { account: acct } = mutateProjectAccount(projectId, account, (a) => {
    if (a.kind !== "debt" && a.kind !== "credit") a.kind = "debt";
    upsertLineOnAccount(a, "debt", {
      label,
      amountUsd: balanceUsd,
      period: "once",
      note,
    });
  });
  appendAction("opsFinance.debtUpsert", {
    projectId,
    account: acct.id,
    label,
    balanceUsd: Number(balanceUsd) || 0,
  });
  return acct;
}

export function addOpsAccount({
  projectId = "ava",
  name,
  kind = "cash",
  balanceUsd = 0,
  note = "",
} = {}) {
  const ledger = loadOpsLedger();
  let proj = findProject(ledger.projects, projectId);
  if (!proj) {
    proj = emptyProject({
      id: String(projectId)
        .toLowerCase()
        .replace(/[^a-z0-9-]+/g, "-"),
      name: projectId,
    });
    ledger.projects.push(proj);
  }
  const ens = ensureAccount(proj.accounts, name, { kind, create: true });
  proj.accounts = ens.accounts;
  if (ens.created || balanceUsd) {
    setAccountBalance(ens.account, balanceUsd, { note });
    ens.account.kind = kind;
  }
  const idx = ledger.projects.findIndex((p) => p.id === proj.id);
  ledger.projects[idx] = proj;
  saveOpsLedger(ledger);
  appendAction("opsFinance.accountAdd", {
    projectId: proj.id,
    account: ens.account.id,
    kind,
  });
  return ens.account;
}

export function formatOpsLedgerPlain(ledger = loadOpsLedger()) {
  const sum = summarizeOpsLedger(ledger);
  const blocks = [
    `Projects: ${sum.projectCount} · accounts: ${sum.accountCount} · bal ${formatUsd(sum.balanceUsd)} · debts ${formatUsd(sum.debtBalanceUsd)}`,
    `~Income ${formatUsd(sum.otherIncomeMonthlyUsd)}/mo · ~expenses ${formatUsd(sum.expensesMonthlyUsd)}/mo · net ${formatUsd(sum.netOtherMonthlyUsd)}/mo`,
  ];
  for (const p of ledger.projects || []) {
    blocks.push("");
    blocks.push(
      formatAccountsPlain(p.accounts || [], {
        title: `Project ${p.name} (${p.id})`,
      }),
    );
  }
  if (sum.staleIds.length) {
    blocks.push("");
    blocks.push(`Stale / never updated: ${sum.staleIds.slice(0, 10).join(", ")}`);
  }
  return blocks.join("\n");
}

export { parsePeriod, findAccount };

/**
 * Per-player finance — opt-in, profile-isolated, multi-account (income + debts).
 * Never mixes with in-game Gold (G) or ops Stripe ledgers.
 */
import { loadPlayerProfile, savePlayerProfileMut } from "./playerProfiles.mjs";
import { personByAuthorId, personByDiscordId, personByTelegramId } from "./people.mjs";
import { formatUsd } from "./stripeFinance.mjs";
import {
  addOpsAccount,
  formatOpsLedgerPlain,
  upsertOpsDebt,
  upsertOpsExpense,
  upsertOpsIncome,
  parsePeriod,
} from "./opsFinanceLedger.mjs";
import {
  ensureAccount,
  formatAccountsPlain,
  migrateFlatToAccounts,
  summarizeAccounts,
  syncLegacyFlatFromAccounts,
  upsertLineOnAccount,
  setAccountBalance,
  emptyAccount,
} from "./financeAccounts.mjs";
import { appendAction } from "./fullLog.mjs";

function emptyFinance() {
  return {
    optIn: false,
    optInAt: null,
    optOutAt: null,
    currency: "USD",
    accounts: [emptyAccount({ id: "acct-default", name: "Default", kind: "cash" })],
    // legacy mirrors
    income: [],
    expenses: [],
    debts: [],
    notes: [],
    lastReviewAt: null,
  };
}

export function normalizePlayerFinance(raw) {
  const base = { ...emptyFinance(), ...(raw || {}) };
  const migrated = migrateFlatToAccounts(base);
  syncLegacyFlatFromAccounts(migrated);
  return migrated;
}

export function getPlayerFinance(discordId) {
  const p = loadPlayerProfile(discordId);
  if (!p?.finance) return emptyFinance();
  return normalizePlayerFinance(p.finance);
}

export function setPlayerFinanceOptIn(discordId, optIn, { username } = {}) {
  const id = String(discordId || "");
  if (!id) return null;
  return savePlayerProfileMut(id, (p) => {
    if (username) p.username = username;
    const fin = normalizePlayerFinance(p.finance || emptyFinance());
    fin.optIn = Boolean(optIn);
    if (optIn) {
      fin.optInAt = Date.now();
      fin.optOutAt = null;
      if (!fin.accounts?.length) {
        fin.accounts = [
          emptyAccount({ id: "acct-default", name: "Default", kind: "cash" }),
        ];
      }
    } else {
      fin.optOutAt = Date.now();
    }
    p.finance = fin;
    return p;
  });
}

export function summarizePlayerFinance(fin) {
  const n = normalizePlayerFinance(fin);
  return summarizeAccounts(n.accounts || []);
}

export function upsertPlayerLine(
  discordId,
  kind,
  { label, amountUsd, period = "month", note = "", account = "default" } = {},
) {
  const id = String(discordId || "");
  if (!id) return { ok: false, reason: "no_id" };
  const profile = savePlayerProfileMut(id, (p) => {
    const fin = normalizePlayerFinance(p.finance || emptyFinance());
    if (!fin.optIn) {
      p._financeErr = "not_opted_in";
      return p;
    }
    const ens = ensureAccount(fin.accounts, account, {
      kind: kind === "debt" ? "debt" : "cash",
      create: true,
    });
    fin.accounts = ens.accounts;
    upsertLineOnAccount(ens.account, kind, {
      label,
      amountUsd,
      period,
      note,
    });
    syncLegacyFlatFromAccounts(fin);
    p.finance = fin;
    delete p._financeErr;
    return p;
  });
  if (profile?._financeErr) {
    return { ok: false, reason: profile._financeErr };
  }
  appendAction("playerFinance.upsert", {
    discordId: id,
    kind,
    account,
    label,
    amountUsd: Number(amountUsd) || 0,
  });
  return { ok: true, finance: profile.finance };
}

export function addPlayerAccount(
  discordId,
  { name, kind = "cash", balanceUsd = 0, note = "" } = {},
) {
  const id = String(discordId || "");
  if (!id) return { ok: false, reason: "no_id" };
  const profile = savePlayerProfileMut(id, (p) => {
    const fin = normalizePlayerFinance(p.finance || emptyFinance());
    if (!fin.optIn) {
      p._financeErr = "not_opted_in";
      return p;
    }
    const ens = ensureAccount(fin.accounts, name, { kind, create: true });
    fin.accounts = ens.accounts;
    setAccountBalance(ens.account, balanceUsd, { note });
    ens.account.kind = kind;
    syncLegacyFlatFromAccounts(fin);
    p.finance = fin;
    delete p._financeErr;
    return p;
  });
  if (profile?._financeErr) {
    return { ok: false, reason: profile._financeErr };
  }
  appendAction("playerFinance.accountAdd", {
    discordId: id,
    name,
    kind,
  });
  return { ok: true, finance: profile.finance };
}

export function formatPlayerFinancePlain(discordId) {
  const fin = getPlayerFinance(discordId);
  if (!fin.optIn) {
    return "Personal finance tracking is off for you. Say “track my finances” to opt in (isolated to your profile — not shared). Multiple accounts OK (checking, PayPal, debts…).";
  }
  const sum = summarizePlayerFinance(fin);
  return [
    "Your tracked finances (private · multi-account):",
    formatAccountsPlain(fin.accounts || [], { title: "Your accounts" }),
    `Totals · bal ${formatUsd(sum.balanceUsd)} · debts ${formatUsd(sum.debtBalanceUsd)} · net flow ~${formatUsd(sum.netMonthlyUsd)}/mo`,
    "Hints: add account PayPal · add income job 2500/mo on checking · add debt student-loan 12000 on debts · add expense rent 1200/mo",
  ].join("\n");
}

export function isOperatorAuthor(authorId, authorName) {
  const p =
    personByAuthorId(authorId, authorName) ||
    personByDiscordId(authorId) ||
    personByTelegramId(authorId);
  return Boolean(p?.roles?.includes("owner") || p?.id === "alexrs94");
}

/**
 * Structured finance commands — returns reply text or null.
 */
export function tryHandleFinanceCommand({
  text = "",
  authorId,
  authorName,
  surface = "discord",
} = {}) {
  const q = String(text || "").trim();
  if (!q) return null;
  const lower = q.toLowerCase();

  if (
    /\b(track\s+my\s+finances?|start\s+tracking\s+my\s+(money|finances?|expenses?)|opt\s*in\s+(to\s+)?finance)\b/i.test(
      lower,
    )
  ) {
    setPlayerFinanceOptIn(authorId, true, { username: authorName });
    return {
      handled: true,
      reply:
        "Got it — multi-account finance on your profile only (income, expenses, debts). Not shared, not mixed with server Gold. Say “my finances”, “add account PayPal”, “add income job 2500/mo on checking”, “add debt car-loan 5000”, or “stop tracking my finances”.",
    };
  }
  if (
    /\b(stop\s+tracking\s+my\s+finances?|opt\s*out\s+(of\s+)?finance|don'?t\s+track\s+my\s+(money|finances?))\b/i.test(
      lower,
    )
  ) {
    setPlayerFinanceOptIn(authorId, false, { username: authorName });
    return {
      handled: true,
      reply:
        "Personal finance tracking off for you. Prior accounts stay on your profile but I won't update or brief them unless you opt back in.",
    };
  }
  if (
    /\b(my\s+finances?|show\s+my\s+(expenses?|income|finances?|accounts?|debts?)|what('?s|\s+is)\s+my\s+(burn|budget))\b/i.test(
      lower,
    )
  ) {
    return { handled: true, reply: formatPlayerFinancePlain(authorId) };
  }

  // add account <name> [kind] [balance]
  const addAcct = q.match(
    /^\s*(?:ava[,:]?\s*)?(?:please\s+)?add\s+account\s+(\S+)(?:\s+(cash|bank|debt|credit|income|paypal|stripe|other))?(?:\s+(\d+(?:\.\d+)?))?\s*$/i,
  );
  if (addAcct) {
    const name = addAcct[1];
    const kind = (addAcct[2] || "cash").toLowerCase();
    const balanceUsd = addAcct[3] != null ? Number(addAcct[3]) : 0;
    const r = addPlayerAccount(authorId, { name, kind, balanceUsd });
    if (!r.ok) {
      return {
        handled: true,
        reply: "Opt in first with “track my finances”.",
      };
    }
    return {
      handled: true,
      reply: `Account “${name}” ready (${kind}).\n${formatPlayerFinancePlain(authorId)}`,
    };
  }

  // add (expense|income|debt) <label> <amount> [/period] [on <account>]
  const addPlayer = q.match(
    /^\s*(?:ava[,:]?\s*)?(?:please\s+)?add\s+(expense|income|debt)\s+(.+?)\s+(\d+(?:\.\d+)?)(?:\s*(?:\/|\s+per\s+)(mo(?:nth)?|yr|year|week|once))?(?:\s+on\s+(\S+))?\s*$/i,
  );
  if (addPlayer) {
    const kind = addPlayer[1].toLowerCase();
    const label = addPlayer[2].trim();
    const amountUsd = Number(addPlayer[3]);
    const period = parsePeriod(addPlayer[4] || (kind === "debt" ? "once" : "month"));
    const account = addPlayer[5] || (kind === "debt" ? "debts" : "default");
    const r = upsertPlayerLine(authorId, kind, {
      label,
      amountUsd,
      period,
      account,
    });
    if (!r.ok) {
      return {
        handled: true,
        reply:
          "Opt in first with “track my finances” — then I can add that line on your private multi-account profile.",
      };
    }
    return {
      handled: true,
      reply: `Logged ${kind} “${label}” at ${formatUsd(amountUsd)}${kind === "debt" ? " owed" : `/${period}`} on account “${account}”.\n${formatPlayerFinancePlain(authorId)}`,
    };
  }

  // Operator project/account commands
  if (!isOperatorAuthor(authorId, authorName)) {
    void surface;
    return null;
  }

  // add project account <project> <name> [kind] [balance]
  const addProjAcct = q.match(
    /^\s*(?:ava[,:]?\s*)?(?:please\s+)?add\s+project\s+account\s+(\S+)\s+(\S+)(?:\s+(cash|bank|debt|credit|income|stripe|project|other))?(?:\s+(\d+(?:\.\d+)?))?\s*$/i,
  );
  if (addProjAcct) {
    const projectId = addProjAcct[1];
    const name = addProjAcct[2];
    const kind = (addProjAcct[3] || "cash").toLowerCase();
    const balanceUsd = addProjAcct[4] != null ? Number(addProjAcct[4]) : 0;
    addOpsAccount({ projectId, name, kind, balanceUsd });
    return {
      handled: true,
      reply: `Project account ${projectId}/${name} (${kind}) ready.\n${formatOpsLedgerPlain()}`,
    };
  }

  // add ops (expense|income|debt) ... [on <account>] [project <id>]
  const addOps = q.match(
    /^\s*(?:ava[,:]?\s*)?(?:please\s+)?(?:ops\s+)?add\s+ops\s+(expense|income|debt)\s+(.+?)\s+(\d+(?:\.\d+)?)(?:\s*(?:\/|\s+per\s+)(mo(?:nth)?|yr|year|week|once))?(?:\s+on\s+(\S+))?(?:\s+project\s+(\S+))?\s*$/i,
  );
  if (addOps) {
    const kind = addOps[1].toLowerCase();
    const label = addOps[2].trim();
    const amountUsd = Number(addOps[3]);
    const period = parsePeriod(addOps[4] || (kind === "debt" ? "once" : "month"));
    const account = addOps[5] || (kind === "debt" ? "debts" : "default");
    const projectId = addOps[6] || (kind === "debt" ? "ava" : "rootmc-ops");
    if (kind === "income") {
      upsertOpsIncome({ label, amountUsd, period, projectId, account });
    } else if (kind === "debt") {
      upsertOpsDebt({ label, balanceUsd: amountUsd, projectId, account });
    } else {
      upsertOpsExpense({ label, amountUsd, period, projectId, account });
    }
    return {
      handled: true,
      reply: `Ops ${kind} logged on ${projectId}/${account}.\n${formatOpsLedgerPlain()}`,
    };
  }

  if (/\b(ops\s+finances?|project\s+finances?|ava\s+accounts?)\b/i.test(lower)) {
    return { handled: true, reply: formatOpsLedgerPlain() };
  }

  void surface;
  return null;
}

